&   , ax_t1, ax_t2, ax_tt, ax_u1, ax_u2, ax_x1, ax_x2, ax_xf, da2, dt, &
&   dt_a1, dt_a2, dt_d1, dt_d2, dt_x1, dt_x2, dt_xf, dxt, hkt, hkt_dt, &
