        amplt = ampl2
        amplt_a2 = 1.0
        sfa = 1.0
        sfa_a1 = 0.
        sfa_a2 = 0.
        sfad = 0.0_8
        sfa_a1d = 0.0_8
        sfa_a2d = 0.0_8
      ELSE
!------ there is transition in X1..X2, "T" is set from N1, N2
