        wf2_a1 = sfa_a1
        wf2_a2d = sfa_a2d
        wf2_a2 = sfa_a2
        wf2_x1 = 0.
        wf2_x2 = 0.
        wf2_xf = 0.
        wf2_x1d = 0.0_8
        wf2_x2d = 0.0_8
