        wf2 = sfx
        wf2_a1 = 0.
        wf2_a2 = 0.
        wf2_x1d = sfx_x1d
        wf2_x1 = sfx_x1
        wf2_x2d = sfx_x2d
        wf2_x2 = sfx_x2
        wf2_xf = sfx_xf
        wf2_a1d = 0.0_8
        wf2_a2d = 0.0_8
