!      WF2_X1 = 0.0
!      WF2_X2 = 0.0
!      WF2_XF = 0.0
!=====================
!
      wf1d = -wf2d
      wf1 = 1.0 - wf2
      wf1_a1d = -wf2_a1d
      wf1_a1 = -wf2_a1
      wf1_a2d = -wf2_a2d
      wf1_a2 = -wf2_a2
      wf1_x1d = -wf2_x1d
      wf1_x1 = -wf2_x1
      wf1_x2d = -wf2_x2d
      wf1_x2 = -wf2_x2
      wf1_xf = -wf2_xf
!
