      xtd = wf1*x1d + x1*wf1d + wf2*x2d + x2*wf2d
      xt = x1*wf1 + x2*wf2
      ttd = wf1*t1d + t1*wf1d + wf2*t2d + t2*wf2d
      tt = t1*wf1 + t2*wf2
      dtd = wf1*d1d + d1*wf1d + wf2*d2d + d2*wf2d
      dt = d1*wf1 + d2*wf2
      utd = wf1*u1d + u1*wf1d + wf2*u2d + u2*wf2d
      ut = u1*wf1 + u2*wf2
!
      xt_a2d = wf1_a2*x1d + x1*wf1_a2d + wf2_a2*x2d + x2*wf2_a2d
      xt_a2 = x1*wf1_a2 + x2*wf2_a2
      tt_a2d = wf1_a2*t1d + t1*wf1_a2d + wf2_a2*t2d + t2*wf2_a2d
      tt_a2 = t1*wf1_a2 + t2*wf2_a2
      dt_a2d = wf1_a2*d1d + d1*wf1_a2d + wf2_a2*d2d + d2*wf2_a2d
      dt_a2 = d1*wf1_a2 + d2*wf2_a2
      ut_a2d = wf1_a2*u1d + u1*wf1_a2d + wf2_a2*u2d + u2*wf2_a2d
      ut_a2 = u1*wf1_a2 + u2*wf2_a2
!
!---- temporarily set "2" variables from "T" for BLKIN
      x2 = xt
      t2d = ttd
      t2 = tt
      d2d = dtd
      d2 = dt
      u2d = utd
      u2 = ut
!
!---- calculate laminar secondary "T" variables HKT, RTT
      CALL BLKIN_D()
!
      hktd = hk2d
      hkt = hk2
      hkt_ttd = hk2_t2d
      hkt_tt = hk2_t2
      hkt_dtd = hk2_d2d
      hkt_dt = hk2_d2
      hkt_utd = hk2_u2d
      hkt_ut = hk2_u2
      hkt_msd = hk2_msd
      hkt_ms = hk2_ms
!
      rttd = rt2d
      rtt = rt2
      rtt_ttd = rt2_t2d
      rtt_tt = rt2_t2
      rtt_utd = rt2_u2d
      rtt_ut = rt2_u2
      rtt_msd = rt2_msd
      rtt_ms = rt2_ms
      rtt_red = rt2_red
      rtt_re = rt2_re
!
!---- restore clobbered "2" variables, except for AMPL2
      amsaved = ampl2d
      amsave = ampl2
      CALL BLC_RESTORE2_D()
      ampl2d = amsaved
      ampl2 = amsave
!
!---- calculate amplification rate AX over current X1-XT interval
      CALL AXSET_D(hk1, hk1d, t1, t1d, rt1, rt1d, ampl1, ampl1d, hkt, &
&            hktd, tt, ttd, rtt, rttd, amplt, ampltd, amcrit, amcritd, &
&            idampv, ax, axd, ax_hk1, ax_hk1d, ax_t1, ax_t1d, ax_rt1, &
