        temp0 = ax_hkt*hkt_ut + ax_rtt*rtt_ut
        ax_a2d = tt_a2*(hkt_tt*ax_hktd+ax_hkt*hkt_ttd+ax_ttd+rtt_tt*&
&         ax_rttd+ax_rtt*rtt_ttd) + temp*tt_a2d + dt_a2*(hkt_dt*ax_hktd+&
&         ax_hkt*hkt_dtd) + ax_hkt*hkt_dt*dt_a2d + ut_a2*(hkt_ut*ax_hktd&
&         +ax_hkt*hkt_utd+rtt_ut*ax_rttd+ax_rtt*rtt_utd) + temp0*ut_a2d &
&         + amplt_a2*ax_atd
        ax_a2 = temp*tt_a2 + ax_hkt*hkt_dt*dt_a2 + temp0*ut_a2 + &
&         amplt_a2*ax_at
!
!---- residual for implicit AMPL2 definition (amplification equation)
        resd = ampl2d - ampl1d - (x2-x1)*axd - ax*(x2d-x1d)
        res = ampl2 - ampl1 - ax*(x2-x1)
        res_a2d = -((x2-x1)*ax_a2d+ax_a2*(x2d-x1d))
        res_a2 = 1.0 - ax_a2*(x2-x1)
!
        da2d = -((resd-res*res_a2d/res_a2)/res_a2)
        da2 = -(res/res_a2)
!
        rlx = 1.0
        dxtd = da2*xt_a2d + xt_a2*da2d
        dxt = xt_a2*da2
        IF (dxt/(x2-x1) .GE. 0.) THEN
          abs0 = dxt/(x2-x1)
        ELSE
          abs0 = -(dxt/(x2-x1))
        END IF
!
        IF (rlx*abs0 .GT. 0.05) THEN
          IF ((x2-x1)/dxt .GE. 0.) THEN
            temp0 = (x2-x1)/dxt
            abs1d = (x2d-x1d-temp0*dxtd)/dxt
            abs1 = temp0
          ELSE
            temp0 = (x2-x1)/dxt
            abs1d = -((x2d-x1d-temp0*dxtd)/dxt)
            abs1 = -temp0
          END IF
          rlxd = 0.05*abs1d
          rlx = 0.05*abs1
        ELSE
          rlxd = 0.0_8
        END IF
        IF (da2 .GE. 0.) THEN
          abs2 = da2
        ELSE
          abs2 = -da2
        END IF
        IF (rlx*abs2 .GT. 1.0) THEN
          IF (1.0/da2 .GE. 0.) THEN
            abs3d = -(da2d/da2**2)
            abs3 = 1.0/da2
          ELSE
            abs3d = da2d/da2**2
            abs3 = -(1.0/da2)
          END IF
          rlxd = abs3d
          rlx = 1.0*abs3
        END IF
        IF (da2 .GE. 0.) THEN
          abs4 = da2
        ELSE
          abs4 = -da2
        END IF
!
!---- check if converged
        IF (abs4 .LT. daeps) THEN
          GOTO 100
        ELSE
!
          ampl2r = ampl2
          amcritr = amcrit
! if ((AMPl2>AMCrit .and. AMPl2 + rlx * da2<AMCrit) .or. (AMPl2<AMCrit .and. AMPl2 + rlx * da2>AMCrit)) then
          IF ((ampl2r .GT. amcritr .AND. ampl2r + rlx*da2 .LT. amcritr) &
&             .OR. (ampl2r .LT. amcritr .AND. ampl2r + rlx*da2 .GT. &
&             amcritr)) THEN
!------ limited Newton step so AMPL2 doesn't step across AMCRIT either way
            ampl2d = amcritd
            ampl2 = amcrit
          ELSE
!------ regular Newton step
            ampl2d = ampl2d + da2*rlxd + rlx*da2d
            ampl2 = ampl2 + rlx*da2
          END IF
        END IF
