      ELSE
!
!---- free transition ... set sensitivities of XT
!
!---- XT( X1 X2 A1 A2 XF ),  TT( T1 T2 A1 A2 X1 X2 XF),   DT( ...
!C    XT    = X1*WF1    + X2*WF2
!C    TT    = T1*WF1    + T2*WF2
!C    DT    = D1*WF1    + D2*WF2
!C    UT    = U1*WF1    + U2*WF2
!
        xt_x1d = wf1d
        xt_x1 = wf1
        tt_t1d = wf1d
        tt_t1 = wf1
        dt_d1d = wf1d
        dt_d1 = wf1
        ut_u1d = wf1d
        ut_u1 = wf1
!
        xt_x2d = wf2d
        xt_x2 = wf2
        tt_t2d = wf2d
        tt_t2 = wf2
        dt_d2d = wf2d
        dt_d2 = wf2
        ut_u2d = wf2d
        ut_u2 = wf2
!
        xt_a1d = wf1_a1*x1d + x1*wf1_a1d + wf2_a1*x2d + x2*wf2_a1d
        xt_a1 = x1*wf1_a1 + x2*wf2_a1
        tt_a1d = wf1_a1*t1d + t1*wf1_a1d + wf2_a1*t2d + t2*wf2_a1d
        tt_a1 = t1*wf1_a1 + t2*wf2_a1
        dt_a1d = wf1_a1*d1d + d1*wf1_a1d + wf2_a1*d2d + d2*wf2_a1d
        dt_a1 = d1*wf1_a1 + d2*wf2_a1
        ut_a1d = wf1_a1*u1d + u1*wf1_a1d + wf2_a1*u2d + u2*wf2_a1d
        ut_a1 = u1*wf1_a1 + u2*wf2_a1
!
!C    XT_A2 = X1*WF1_A2 + X2*WF2_A2
!C    TT_A2 = T1*WF1_A2 + T2*WF2_A2
!C    DT_A2 = D1*WF1_A2 + D2*WF2_A2
!C    UT_A2 = U1*WF1_A2 + U2*WF2_A2
!
        xt_x1d = wf1_x1*x1d + x1*wf1_x1d + wf2_x1*x2d + x2*wf2_x1d + &
&         xt_x1d
        xt_x1 = x1*wf1_x1 + x2*wf2_x1 + xt_x1
        tt_x1d = wf1_x1*t1d + t1*wf1_x1d + wf2_x1*t2d + t2*wf2_x1d
        tt_x1 = t1*wf1_x1 + t2*wf2_x1
        dt_x1d = wf1_x1*d1d + d1*wf1_x1d + wf2_x1*d2d + d2*wf2_x1d
        dt_x1 = d1*wf1_x1 + d2*wf2_x1
        ut_x1d = wf1_x1*u1d + u1*wf1_x1d + wf2_x1*u2d + u2*wf2_x1d
        ut_x1 = u1*wf1_x1 + u2*wf2_x1
!
        xt_x2d = wf1_x2*x1d + x1*wf1_x2d + wf2_x2*x2d + x2*wf2_x2d + &
&         xt_x2d
        xt_x2 = x1*wf1_x2 + x2*wf2_x2 + xt_x2
        tt_x2d = wf1_x2*t1d + t1*wf1_x2d + wf2_x2*t2d + t2*wf2_x2d
        tt_x2 = t1*wf1_x2 + t2*wf2_x2
        dt_x2d = wf1_x2*d1d + d1*wf1_x2d + wf2_x2*d2d + d2*wf2_x2d
        dt_x2 = d1*wf1_x2 + d2*wf2_x2
        ut_x2d = wf1_x2*u1d + u1*wf1_x2d + wf2_x2*u2d + u2*wf2_x2d
        ut_x2 = u1*wf1_x2 + u2*wf2_x2
!
        xt_xf = x1*wf1_xf + x2*wf2_xf
        tt_xf = t1*wf1_xf + t2*wf2_xf
        dt_xf = d1*wf1_xf + d2*wf2_xf
        ut_xf = u1*wf1_xf + u2*wf2_xf
!
!---- at this point, AX = AX( HK1, T1, RT1, A1, HKT, TT, RTT, AT )
!
!---- set sensitivities of AX( T1 D1 U1 A1 T2 D2 U2 A2 MS RE )
        temp0 = ax_hkt*hkt_tt + ax_tt + ax_rtt*rtt_tt
        ax_t1d = hk1_t1*ax_hk1d + ax_hk1*hk1_t1d + ax_t1d + rt1_t1*&
&         ax_rt1d + ax_rt1*rt1_t1d + tt_t1*(hkt_tt*ax_hktd+ax_hkt*&
&         hkt_ttd+ax_ttd+rtt_tt*ax_rttd+ax_rtt*rtt_ttd) + temp0*tt_t1d
        ax_t1 = ax_hk1*hk1_t1 + ax_t1 + ax_rt1*rt1_t1 + temp0*tt_t1
        ax_d1d = hk1_d1*ax_hk1d + ax_hk1*hk1_d1d + dt_d1*(hkt_dt*ax_hktd&
&         +ax_hkt*hkt_dtd) + ax_hkt*hkt_dt*dt_d1d
        ax_d1 = ax_hk1*hk1_d1 + ax_hkt*hkt_dt*dt_d1
        temp0 = ax_hkt*hkt_ut + ax_rtt*rtt_ut
        ax_u1d = hk1_u1*ax_hk1d + ax_hk1*hk1_u1d + rt1_u1*ax_rt1d + &
&         ax_rt1*rt1_u1d + ut_u1*(hkt_ut*ax_hktd+ax_hkt*hkt_utd+rtt_ut*&
&         ax_rttd+ax_rtt*rtt_utd) + temp0*ut_u1d
        ax_u1 = ax_hk1*hk1_u1 + ax_rt1*rt1_u1 + temp0*ut_u1
        temp0 = ax_hkt*hkt_tt + ax_tt + ax_rtt*rtt_tt
        temp = ax_hkt*hkt_ut + ax_rtt*rtt_ut
        ax_a1d = ax_a1d + tt_a1*(hkt_tt*ax_hktd+ax_hkt*hkt_ttd+ax_ttd+&
&         rtt_tt*ax_rttd+ax_rtt*rtt_ttd) + temp0*tt_a1d + dt_a1*(hkt_dt*&
&         ax_hktd+ax_hkt*hkt_dtd) + ax_hkt*hkt_dt*dt_a1d + ut_a1*(hkt_ut&
&         *ax_hktd+ax_hkt*hkt_utd+rtt_ut*ax_rttd+ax_rtt*rtt_utd) + temp*&
&         ut_a1d
        ax_a1 = ax_a1 + temp0*tt_a1 + ax_hkt*hkt_dt*dt_a1 + temp*ut_a1
        temp0 = ax_hkt*hkt_tt + ax_tt + ax_rtt*rtt_tt
        temp = ax_hkt*hkt_ut + ax_rtt*rtt_ut
        ax_x1d = tt_x1*(hkt_tt*ax_hktd+ax_hkt*hkt_ttd+ax_ttd+rtt_tt*&
&         ax_rttd+ax_rtt*rtt_ttd) + temp0*tt_x1d + dt_x1*(hkt_dt*ax_hktd&
&         +ax_hkt*hkt_dtd) + ax_hkt*hkt_dt*dt_x1d + ut_x1*(hkt_ut*&
&         ax_hktd+ax_hkt*hkt_utd+rtt_ut*ax_rttd+ax_rtt*rtt_utd) + temp*&
&         ut_x1d
        ax_x1 = temp0*tt_x1 + ax_hkt*hkt_dt*dt_x1 + temp*ut_x1
!
        temp0 = ax_hkt*hkt_tt + ax_tt + ax_rtt*rtt_tt
        ax_t2d = tt_t2*(hkt_tt*ax_hktd+ax_hkt*hkt_ttd+ax_ttd+rtt_tt*&
&         ax_rttd+ax_rtt*rtt_ttd) + temp0*tt_t2d
        ax_t2 = temp0*tt_t2
        ax_d2d = dt_d2*(hkt_dt*ax_hktd+ax_hkt*hkt_dtd) + ax_hkt*hkt_dt*&
&         dt_d2d
        ax_d2 = ax_hkt*hkt_dt*dt_d2
        temp0 = ax_hkt*hkt_ut + ax_rtt*rtt_ut
        ax_u2d = ut_u2*(hkt_ut*ax_hktd+ax_hkt*hkt_utd+rtt_ut*ax_rttd+&
&         ax_rtt*rtt_utd) + temp0*ut_u2d
        ax_u2 = temp0*ut_u2
        temp0 = ax_hkt*hkt_tt + ax_tt + ax_rtt*rtt_tt
        temp = ax_hkt*hkt_ut + ax_rtt*rtt_ut
        ax_a2d = amplt_a2*ax_atd + tt_a2*(hkt_tt*ax_hktd+ax_hkt*hkt_ttd+&
&         ax_ttd+rtt_tt*ax_rttd+ax_rtt*rtt_ttd) + temp0*tt_a2d + dt_a2*(&
&         hkt_dt*ax_hktd+ax_hkt*hkt_dtd) + ax_hkt*hkt_dt*dt_a2d + ut_a2*&
