&         temp*ut_a2
        temp0 = ax_hkt*hkt_tt + ax_tt + ax_rtt*rtt_tt
        temp = ax_hkt*hkt_ut + ax_rtt*rtt_ut
        ax_x2d = tt_x2*(hkt_tt*ax_hktd+ax_hkt*hkt_ttd+ax_ttd+rtt_tt*&
&         ax_rttd+ax_rtt*rtt_ttd) + temp0*tt_x2d + dt_x2*(hkt_dt*ax_hktd&
&         +ax_hkt*hkt_dtd) + ax_hkt*hkt_dt*dt_x2d + ut_x2*(hkt_ut*&
&         ax_hktd+ax_hkt*hkt_utd+rtt_ut*ax_rttd+ax_rtt*rtt_utd) + temp*&
&         ut_x2d
        ax_x2 = temp0*tt_x2 + ax_hkt*hkt_dt*dt_x2 + temp*ut_x2
!
        ax_xf = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_xf + ax_hkt*&
&         hkt_dt*dt_xf + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_xf
