        ax_msd = hkt_ms*ax_hktd + ax_hkt*hkt_msd + rtt_ms*ax_rttd + &
&         ax_rtt*rtt_msd + hk1_ms*ax_hk1d + ax_hk1*hk1_msd + rt1_ms*&
