!---- set sensitivities of residual RES
!CC   RES  = AMPL2 - AMPL1 - AX*(X2-X1)
        z_axd = x1d - x2d
        z_ax = -(x2-x1)
!
        z_a1d = ax_a1*z_axd + z_ax*ax_a1d
        z_a1 = z_ax*ax_a1 - 1.0
        z_t1d = ax_t1*z_axd + z_ax*ax_t1d
        z_t1 = z_ax*ax_t1
        z_d1d = ax_d1*z_axd + z_ax*ax_d1d
        z_d1 = z_ax*ax_d1
        z_u1d = ax_u1*z_axd + z_ax*ax_u1d
        z_u1 = z_ax*ax_u1
        z_x1d = ax_x1*z_axd + z_ax*ax_x1d + axd
        z_x1 = z_ax*ax_x1 + ax
!
        z_a2d = ax_a2*z_axd + z_ax*ax_a2d
        z_a2 = z_ax*ax_a2 + 1.0
        z_t2d = ax_t2*z_axd + z_ax*ax_t2d
        z_t2 = z_ax*ax_t2
        z_d2d = ax_d2*z_axd + z_ax*ax_d2d
        z_d2 = z_ax*ax_d2
        z_u2d = ax_u2*z_axd + z_ax*ax_u2d
        z_u2 = z_ax*ax_u2
        z_x2d = ax_x2*z_axd + z_ax*ax_x2d - axd
        z_x2 = z_ax*ax_x2 - ax
!
        z_xf = z_ax*ax_xf
        z_msd = ax_ms*z_axd + z_ax*ax_msd
        z_ms = z_ax*ax_ms
        z_red = ax_re*z_axd + z_ax*ax_red
        z_re = z_ax*ax_re
