!---- set sensitivities of XT, with RES being stationary for A2 constraint
        temp0 = xt_a2*z_a1/z_a2
        xt_a1d = xt_a1d - (z_a1*xt_a2d+xt_a2*z_a1d-temp0*z_a2d)/z_a2
        xt_a1 = xt_a1 - temp0
        temp0 = xt_a2*z_t1/z_a2
