        xt_x1 = xt_x1 - temp0
        temp0 = xt_a2*z_t2/z_a2
        xt_t2d = -((z_t2*xt_a2d+xt_a2*z_t2d-temp0*z_a2d)/z_a2)
        xt_t2 = -temp0
        temp0 = xt_a2*z_d2/z_a2
        xt_d2d = -((z_d2*xt_a2d+xt_a2*z_d2d-temp0*z_a2d)/z_a2)
        xt_d2 = -temp0
        temp0 = xt_a2*z_u2/z_a2
