        xt_x2 = xt_x2 - temp0
        temp0 = xt_a2*z_ms/z_a2
        xt_msd = -((z_ms*xt_a2d+xt_a2*z_msd-temp0*z_a2d)/z_a2)
        xt_ms = -temp0
        temp0 = xt_a2*z_re/z_a2
        xt_red = -((z_re*xt_a2d+xt_a2*z_red-temp0*z_a2d)/z_a2)
        xt_re = -temp0
        xt_xf = 0.0
