    hc2_u2d = hk2_u2*hc2_hk2d + hc2_hk2*hk2_u2d + m2_u2*hc2_m2d + hc2_m2&
&     *m2_u2d
    hc2_u2 = hc2_hk2*hk2_u2 + hc2_m2*m2_u2
    hc2_t2d = hk2_t2*hc2_hk2d + hc2_hk2*hk2_t2d
