    hc2_d2d = hk2_d2*hc2_hk2d + hc2_hk2*hk2_d2d
    hc2_d2 = hc2_hk2*hk2_d2
    hc2_msd = hk2_ms*hc2_hk2d + hc2_hk2*hk2_msd + m2_ms*hc2_m2d + hc2_m2&
