    hs2_u2d = hk2_u2*hs2_hk2d + hs2_hk2*hk2_u2d + rt2_u2*hs2_rt2d + &
&     hs2_rt2*rt2_u2d + m2_u2*hs2_m2d + hs2_m2*m2_u2d
