    us2_d2d = hs2_d2*us2_hs2d + us2_hs2*hs2_d2d + hk2_d2*us2_hk2d + &
&     us2_hk2*hk2_d2d + h2_d2*us2_h2d + us2_h2*h2_d2d
    us2_d2 = us2_hs2*hs2_d2 + us2_hk2*hk2_d2 + us2_h2*h2_d2
    us2_msd = hs2_ms*us2_hs2d + us2_hs2*hs2_msd + hk2_ms*us2_hk2d + &
