      us2_t2 = 0.
      us2_d2 = 0.
      us2_ms = 0.
      us2_re = 0.
      us2_u2d = 0.0_8
      us2_msd = 0.0_8
      us2d = 0.0_8
      us2_red = 0.0_8
      us2_t2d = 0.0_8
      us2_d2d = 0.0_8
