    temp9 = hk2*hk2*cq2
    temp8 = usb*h2*temp9
    temp7 = hs2*hkb*hkc*hkc_rt2/temp8
    cq2_rt2d = temp10*(hkc*hkc_rt2*(hkb*hs2d+hs2*hkbd)+hs2*hkb*(hkc_rt2*&
&     hkcd+hkc*hkc_rt2d)-temp7*(temp9*(h2*usbd+usb*h2d)+usb*h2*(cq2*2*&
&     hk2*hk2d+hk2**2*cq2d)))/temp8
    cq2_rt2 = temp10*temp7
    temp10 = h2*h2*(hk2*hk2)
    temp9 = temp10*usb*cq2
    temp8 = hs2*hkb*(hkc*hkc)/temp9
    cq2_h2d = -(ctcon*0.5*(hkc**2*(hkb*hs2d+hs2*hkbd)+hs2*hkb*2*hkc*hkcd&
&     -temp8*(usb*cq2*(hk2**2*2*h2*h2d+h2**2*2*hk2*hk2d)+temp10*(cq2*&
&     usbd+usb*cq2d)))/temp9)
    cq2_h2 = -(ctcon*0.5*temp8)
!
    cq2_u2d = hs2_u2*cq2_hs2d + cq2_hs2*hs2_u2d + us2_u2*cq2_us2d + &
&     cq2_us2*us2_u2d + hk2_u2*cq2_hk2d + cq2_hk2*hk2_u2d
    cq2_u2 = cq2_hs2*hs2_u2 + cq2_us2*us2_u2 + cq2_hk2*hk2_u2
    cq2_t2d = hs2_t2*cq2_hs2d + cq2_hs2*hs2_t2d + us2_t2*cq2_us2d + &
&     cq2_us2*us2_t2d + hk2_t2*cq2_hk2d + cq2_hk2*hk2_t2d
