    cq2_t2d = cq2_t2d + h2_t2*cq2_h2d + cq2_h2*h2_t2d + rt2_t2*cq2_rt2d &
&     + cq2_rt2*rt2_t2d
    cq2_t2 = cq2_t2 + cq2_h2*h2_t2 + cq2_rt2*rt2_t2
    cq2_d2d = cq2_d2d + h2_d2*cq2_h2d + cq2_h2*h2_d2d
    cq2_d2 = cq2_d2 + cq2_h2*h2_d2
    cq2_msd = cq2_msd + rt2_ms*cq2_rt2d + cq2_rt2*rt2_msd
    cq2_ms = cq2_ms + cq2_rt2*rt2_ms
    cq2_red = cq2_red + rt2_re*cq2_rt2d + cq2_rt2*rt2_red
    cq2_re = cq2_re + cq2_rt2*rt2_re
!
!
!---- set skin friction coefficient
    IF (ityp .EQ. 3) THEN
!----- wake
      cf2 = 0.
      cf2_hk2 = 0.
      cf2_rt2 = 0.
      cf2_m2 = 0.
      cf2d = 0.0_8
      cf2_rt2d = 0.0_8
      cf2_hk2d = 0.0_8
      cf2_m2d = 0.0_8
    ELSE IF (ityp .EQ. 1) THEN
!----- laminar
      CALL CFL_D(hk2, hk2d, rt2, rt2d, m2, cf2, cf2d, cf2_hk2, cf2_hk2d&
&          , cf2_rt2, cf2_rt2d, cf2_m2)
      cf2_m2d = 0.0_8
    ELSE
!----- turbulent
      CALL CFT_D(hk2, hk2d, rt2, rt2d, m2, m2d, cf2, cf2d, cf2_hk2, &
&          cf2_hk2d, cf2_rt2, cf2_rt2d, cf2_m2, cf2_m2d)
      CALL CFL_D(hk2, hk2d, rt2, rt2d, m2, cf2l, cf2ld, cf2l_hk2, &
&          cf2l_hk2d, cf2l_rt2, cf2l_rt2d, cf2l_m2)
      cf2r = cf2
! if (cf2l>CF2) then
      IF (cf2l .GT. cf2r) THEN
!------- laminar Cf is greater than turbulent Cf -- use laminar
!-       (this will only occur for unreasonably small Rtheta)
!cc      write(*,*) 'Cft Cfl Rt Hk:', CF2, CF2L, RT2, HK2, X2
        cf2d = cf2ld
        cf2 = cf2l
        cf2_hk2d = cf2l_hk2d
        cf2_hk2 = cf2l_hk2
        cf2_rt2d = cf2l_rt2d
        cf2_rt2 = cf2l_rt2
        cf2_m2 = cf2l_m2
        cf2_m2d = 0.0_8
      END IF
    END IF
!
    cf2_u2d = hk2_u2*cf2_hk2d + cf2_hk2*hk2_u2d + rt2_u2*cf2_rt2d + &
&     cf2_rt2*rt2_u2d + m2_u2*cf2_m2d + cf2_m2*m2_u2d
    cf2_u2 = cf2_hk2*hk2_u2 + cf2_rt2*rt2_u2 + cf2_m2*m2_u2
    cf2_t2d = hk2_t2*cf2_hk2d + cf2_hk2*hk2_t2d + rt2_t2*cf2_rt2d + &
&     cf2_rt2*rt2_t2d
    cf2_t2 = cf2_hk2*hk2_t2 + cf2_rt2*rt2_t2
    cf2_d2d = hk2_d2*cf2_hk2d + cf2_hk2*hk2_d2d
    cf2_d2 = cf2_hk2*hk2_d2
    cf2_msd = hk2_ms*cf2_hk2d + cf2_hk2*hk2_msd + rt2_ms*cf2_rt2d + &
&     cf2_rt2*rt2_msd + m2_ms*cf2_m2d + cf2_m2*m2_msd
    cf2_ms = cf2_hk2*hk2_ms + cf2_rt2*rt2_ms + cf2_m2*m2_ms
    cf2_red = rt2_re*cf2_rt2d + cf2_rt2*rt2_red
    cf2_re = cf2_rt2*rt2_re
!
!---- dissipation function    2 CD / H*
    IF (ityp .EQ. 1) THEN
!
!----- laminar
      CALL DIL_D(hk2, hk2d, rt2, rt2d, di2, di2d, di2_hk2, di2_hk2d, &
&          di2_rt2, di2_rt2d)
!
      di2_u2d = hk2_u2*di2_hk2d + di2_hk2*hk2_u2d + rt2_u2*di2_rt2d + &
&       di2_rt2*rt2_u2d
      di2_u2 = di2_hk2*hk2_u2 + di2_rt2*rt2_u2
      di2_t2d = hk2_t2*di2_hk2d + di2_hk2*hk2_t2d + rt2_t2*di2_rt2d + &
&       di2_rt2*rt2_t2d
      di2_t2 = di2_hk2*hk2_t2 + di2_rt2*rt2_t2
      di2_d2d = hk2_d2*di2_hk2d + di2_hk2*hk2_d2d
      di2_d2 = di2_hk2*hk2_d2
      di2_s2 = 0.
      di2_msd = hk2_ms*di2_hk2d + di2_hk2*hk2_msd + rt2_ms*di2_rt2d + &
&       di2_rt2*rt2_msd
      di2_ms = di2_hk2*hk2_ms + di2_rt2*rt2_ms
      di2_red = rt2_re*di2_rt2d + di2_rt2*rt2_red
      di2_re = di2_rt2*rt2_re
!
      di2_s2d = 0.0_8
    ELSE IF (ityp .EQ. 2) THEN
!
!CC       CALL DIT(     HS2,     US2,     CF2,     S2, DI2,
!CC     &           DI2_HS2, DI2_US2, DI2_CF2, DI2_S2      )
!
!----- turbulent wall contribution
      CALL CFT_D(hk2, hk2d, rt2, rt2d, m2, m2d, cf2t, cf2td, cf2t_hk2, &
&          cf2t_hk2d, cf2t_rt2, cf2t_rt2d, cf2t_m2, cf2t_m2d)
      cf2t_u2d = hk2_u2*cf2t_hk2d + cf2t_hk2*hk2_u2d + rt2_u2*cf2t_rt2d &
&       + cf2t_rt2*rt2_u2d + m2_u2*cf2t_m2d + cf2t_m2*m2_u2d
      cf2t_u2 = cf2t_hk2*hk2_u2 + cf2t_rt2*rt2_u2 + cf2t_m2*m2_u2
      cf2t_t2d = hk2_t2*cf2t_hk2d + cf2t_hk2*hk2_t2d + rt2_t2*cf2t_rt2d &
&       + cf2t_rt2*rt2_t2d
      cf2t_t2 = cf2t_hk2*hk2_t2 + cf2t_rt2*rt2_t2
      cf2t_d2d = hk2_d2*cf2t_hk2d + cf2t_hk2*hk2_d2d
      cf2t_d2 = cf2t_hk2*hk2_d2
      cf2t_msd = hk2_ms*cf2t_hk2d + cf2t_hk2*hk2_msd + rt2_ms*cf2t_rt2d &
&       + cf2t_rt2*rt2_msd + m2_ms*cf2t_m2d + cf2t_m2*m2_msd
      cf2t_ms = cf2t_hk2*hk2_ms + cf2t_rt2*rt2_ms + cf2t_m2*m2_ms
      cf2t_red = rt2_re*cf2t_rt2d + cf2t_rt2*rt2_red
      cf2t_re = cf2t_rt2*rt2_re
!
      temp10 = cf2t*us2/hs2
      di2d = 2.0*0.5*(us2*cf2td+cf2t*us2d-temp10*hs2d)/hs2
      di2 = 2.0*0.5*temp10
      temp10 = cf2t*us2/(hs2*hs2)
      di2_hs2d = -(2.0*0.5*(us2*cf2td+cf2t*us2d-temp10*2*hs2*hs2d)/hs2**&
&       2)
      di2_hs2 = -(2.0*0.5*temp10)
      di2_us2d = 2.0*0.5*(cf2td-cf2t*hs2d/hs2)/hs2
      di2_us2 = 0.5*cf2t*2.0/hs2
      di2_cf2td = 2.0*0.5*(us2d-us2*hs2d/hs2)/hs2
      di2_cf2t = 0.5*us2*2.0/hs2
!
      di2_s2 = 0.0
      di2_u2d = hs2_u2*di2_hs2d + di2_hs2*hs2_u2d + us2_u2*di2_us2d + &
&       di2_us2*us2_u2d + cf2t_u2*di2_cf2td + di2_cf2t*cf2t_u2d
      di2_u2 = di2_hs2*hs2_u2 + di2_us2*us2_u2 + di2_cf2t*cf2t_u2
      di2_t2d = hs2_t2*di2_hs2d + di2_hs2*hs2_t2d + us2_t2*di2_us2d + &
&       di2_us2*us2_t2d + cf2t_t2*di2_cf2td + di2_cf2t*cf2t_t2d
      di2_t2 = di2_hs2*hs2_t2 + di2_us2*us2_t2 + di2_cf2t*cf2t_t2
      di2_d2d = hs2_d2*di2_hs2d + di2_hs2*hs2_d2d + us2_d2*di2_us2d + &
&       di2_us2*us2_d2d + cf2t_d2*di2_cf2td + di2_cf2t*cf2t_d2d
      di2_d2 = di2_hs2*hs2_d2 + di2_us2*us2_d2 + di2_cf2t*cf2t_d2
      di2_msd = hs2_ms*di2_hs2d + di2_hs2*hs2_msd + us2_ms*di2_us2d + &
&       di2_us2*us2_msd + cf2t_ms*di2_cf2td + di2_cf2t*cf2t_msd
      di2_ms = di2_hs2*hs2_ms + di2_us2*us2_ms + di2_cf2t*cf2t_ms
      di2_red = hs2_re*di2_hs2d + di2_hs2*hs2_red + us2_re*di2_us2d + &
&       di2_us2*us2_red + cf2t_re*di2_cf2td + di2_cf2t*cf2t_red
      di2_re = di2_hs2*hs2_re + di2_us2*us2_re + di2_cf2t*cf2t_re
!
!
!----- set minimum Hk for wake layer to still exist
      grtd = rt2d/rt2
      grt = LOG(rt2)
      hmind = -(2.1*grtd/grt**2)
      hmin = 1.0 + 2.1/grt
      temp10 = 2.1/(grt*grt*rt2)
      hm_rt2d = temp10*(rt2*2*grt*grtd+grt**2*rt2d)/(grt**2*rt2)
      hm_rt2 = -temp10
!
!----- set factor DFAC for correcting wall dissipation for very low Hk
      temp10 = (hk2-1.0)/(hmin-1.0)
      fld = (hk2d-temp10*hmind)/(hmin-1.0)
      fl = temp10
      fl_hk2d = -(hmind/(hmin-1.0)**2)
      fl_hk2 = 1.0/(hmin-1.0)
      temp10 = fl*hm_rt2/(hmin-1.0)
      fl_rt2d = -((hm_rt2*fld+fl*hm_rt2d-temp10*hmind)/(hmin-1.0))
      fl_rt2 = -temp10
!
      tfld = (1.0-TANH(fl)**2)*fld
      tfl = TANH(fl)
      dfacd = 0.5*tfld
      dfac = 0.5 + 0.5*tfl
      df_fld = -(0.5*2*tfl*tfld)
      df_fl = 0.5*(1.0-tfl**2)
!
      df_hk2d = fl_hk2*df_fld + df_fl*fl_hk2d
      df_hk2 = df_fl*fl_hk2
      df_rt2d = fl_rt2*df_fld + df_fl*fl_rt2d
      df_rt2 = df_fl*fl_rt2
!
      di2_s2d = di2_s2*dfacd
      di2_s2 = di2_s2*dfac
      temp10 = df_hk2*hk2_u2 + df_rt2*rt2_u2
      di2_u2d = dfac*di2_u2d + di2_u2*dfacd + temp10*di2d + di2*(hk2_u2*&
&       df_hk2d+df_hk2*hk2_u2d+rt2_u2*df_rt2d+df_rt2*rt2_u2d)
      di2_u2 = di2_u2*dfac + di2*temp10
      temp10 = df_hk2*hk2_t2 + df_rt2*rt2_t2
      di2_t2d = dfac*di2_t2d + di2_t2*dfacd + temp10*di2d + di2*(hk2_t2*&
&       df_hk2d+df_hk2*hk2_t2d+rt2_t2*df_rt2d+df_rt2*rt2_t2d)
      di2_t2 = di2_t2*dfac + di2*temp10
      di2_d2d = dfac*di2_d2d + di2_d2*dfacd + hk2_d2*(df_hk2*di2d+di2*&
&       df_hk2d) + di2*df_hk2*hk2_d2d
      di2_d2 = di2_d2*dfac + di2*(df_hk2*hk2_d2)
      temp10 = df_hk2*hk2_ms + df_rt2*rt2_ms
      di2_msd = dfac*di2_msd + di2_ms*dfacd + temp10*di2d + di2*(hk2_ms*&
&       df_hk2d+df_hk2*hk2_msd+rt2_ms*df_rt2d+df_rt2*rt2_msd)
      di2_ms = di2_ms*dfac + di2*temp10
      di2_red = dfac*di2_red + di2_re*dfacd + rt2_re*(df_rt2*di2d+di2*&
&       df_rt2d) + di2*df_rt2*rt2_red
      di2_re = di2_re*dfac + di2*(df_rt2*rt2_re)
      di2d = dfac*di2d + di2*dfacd
      di2 = di2*dfac
!
    ELSE
!
!----- zero wall contribution for wake
      di2 = 0.0
      di2_s2 = 0.0
      di2_u2 = 0.0
      di2_t2 = 0.0
      di2_d2 = 0.0
      di2_ms = 0.0
      di2_re = 0.0
!
      di2_t2d = 0.0_8
      di2_d2d = 0.0_8
      di2d = 0.0_8
      di2_u2d = 0.0_8
      di2_msd = 0.0_8
      di2_s2d = 0.0_8
      di2_red = 0.0_8
    END IF
!
!
!---- Add on turbulent outer layer contribution
    IF (ityp .NE. 1) THEN
!
      temp10 = (-us2+0.995)/hs2
      ddd = 2.0*(temp10*2*s2*s2d+s2**2*(-us2d-temp10*hs2d)/hs2)
      dd = 2.0*(s2*s2*temp10)
      temp10 = s2*s2*(-us2+0.995)/(hs2*hs2)
      dd_hs2d = -(2.0*((0.995-us2)*2*s2*s2d-s2**2*us2d-temp10*2*hs2*hs2d&
&       )/hs2**2)
      dd_hs2 = -(2.0*temp10)
      temp10 = s2*s2/hs2
      dd_us2d = -(2.0*(2*s2*s2d-temp10*hs2d)/hs2)
      dd_us2 = -(2.0*temp10)
      temp10 = s2/hs2
      dd_s2d = 2.0**2*((0.995-us2)*(s2d-temp10*hs2d)/hs2-temp10*us2d)
      dd_s2 = 2.0*2.0*((0.995-us2)*temp10)
!
      di2d = di2d + ddd
      di2 = di2 + dd
      di2_s2d = dd_s2d
      di2_s2 = dd_s2
      di2_u2d = di2_u2d + hs2_u2*dd_hs2d + dd_hs2*hs2_u2d + us2_u2*&
&       dd_us2d + dd_us2*us2_u2d
      di2_u2 = di2_u2 + dd_hs2*hs2_u2 + dd_us2*us2_u2
      di2_t2d = di2_t2d + hs2_t2*dd_hs2d + dd_hs2*hs2_t2d + us2_t2*&
&       dd_us2d + dd_us2*us2_t2d
      di2_t2 = di2_t2 + dd_hs2*hs2_t2 + dd_us2*us2_t2
      di2_d2d = di2_d2d + hs2_d2*dd_hs2d + dd_hs2*hs2_d2d + us2_d2*&
&       dd_us2d + dd_us2*us2_d2d
      di2_d2 = di2_d2 + dd_hs2*hs2_d2 + dd_us2*us2_d2
      di2_msd = di2_msd + hs2_ms*dd_hs2d + dd_hs2*hs2_msd + us2_ms*&
&       dd_us2d + dd_us2*us2_msd
      di2_ms = di2_ms + dd_hs2*hs2_ms + dd_us2*us2_ms
      di2_red = di2_red + hs2_re*dd_hs2d + dd_hs2*hs2_red + us2_re*&
&       dd_us2d + dd_us2*us2_red
      di2_re = di2_re + dd_hs2*hs2_re + dd_us2*us2_re
!
!----- add laminar stress contribution to outer layer CD
!###
      temp10 = (-us2+0.995)*(-us2+0.995)/(rt2*hs2)
      ddd = 2.0*0.15*(-(2*(0.995-us2)*us2d)-temp10*(hs2*rt2d+rt2*hs2d))/&
&       (rt2*hs2)
      dd = 2.0*0.15*temp10
      temp10 = (-us2+0.995)/(rt2*hs2)
      dd_us2d = -(2.*2.0*0.15*(-us2d-temp10*(hs2*rt2d+rt2*hs2d))/(rt2*&
&       hs2))
      dd_us2 = -(2.*2.0*0.15*temp10)
      dd_hs2d = -((ddd-dd*hs2d/hs2)/hs2)
      dd_hs2 = -(dd/hs2)
      dd_rt2d = -((ddd-dd*rt2d/rt2)/rt2)
      dd_rt2 = -(dd/rt2)
!
      di2d = di2d + ddd
      di2 = di2 + dd
      di2_u2d = di2_u2d + hs2_u2*dd_hs2d + dd_hs2*hs2_u2d + us2_u2*&
&       dd_us2d + dd_us2*us2_u2d + rt2_u2*dd_rt2d + dd_rt2*rt2_u2d
      di2_u2 = di2_u2 + dd_hs2*hs2_u2 + dd_us2*us2_u2 + dd_rt2*rt2_u2
      di2_t2d = di2_t2d + hs2_t2*dd_hs2d + dd_hs2*hs2_t2d + us2_t2*&
&       dd_us2d + dd_us2*us2_t2d + rt2_t2*dd_rt2d + dd_rt2*rt2_t2d
      di2_t2 = di2_t2 + dd_hs2*hs2_t2 + dd_us2*us2_t2 + dd_rt2*rt2_t2
      di2_d2d = di2_d2d + hs2_d2*dd_hs2d + dd_hs2*hs2_d2d + us2_d2*&
&       dd_us2d + dd_us2*us2_d2d
      di2_d2 = di2_d2 + dd_hs2*hs2_d2 + dd_us2*us2_d2
      di2_msd = di2_msd + hs2_ms*dd_hs2d + dd_hs2*hs2_msd + us2_ms*&
&       dd_us2d + dd_us2*us2_msd + rt2_ms*dd_rt2d + dd_rt2*rt2_msd
      di2_ms = di2_ms + dd_hs2*hs2_ms + dd_us2*us2_ms + dd_rt2*rt2_ms
      di2_red = di2_red + hs2_re*dd_hs2d + dd_hs2*hs2_red + us2_re*&
&       dd_us2d + dd_us2*us2_red + rt2_re*dd_rt2d + dd_rt2*rt2_red
      di2_re = di2_re + dd_hs2*hs2_re + dd_us2*us2_re + dd_rt2*rt2_re
!
    END IF
!
!
    di2r = di2
    IF (ityp .EQ. 2) THEN
      CALL DIL_D(hk2, hk2d, rt2, rt2d, di2l, di2ld, di2l_hk2, di2l_hk2d&
&          , di2l_rt2, di2l_rt2d)
!
! if (di2l>DI2) then
      IF (di2l .GT. di2r) THEN
!------- laminar CD is greater than turbulent CD -- use laminar
!-       (this will only occur for unreasonably small Rtheta)
!cc       write(*,*) 'CDt CDl Rt Hk:', DI2, DI2L, RT2, HK2
        di2d = di2ld
        di2 = di2l
        di2_s2 = 0.
        di2_u2d = hk2_u2*di2l_hk2d + di2l_hk2*hk2_u2d + rt2_u2*di2l_rt2d&
&         + di2l_rt2*rt2_u2d
        di2_u2 = di2l_hk2*hk2_u2 + di2l_rt2*rt2_u2
        di2_t2d = hk2_t2*di2l_hk2d + di2l_hk2*hk2_t2d + rt2_t2*di2l_rt2d&
&         + di2l_rt2*rt2_t2d
        di2_t2 = di2l_hk2*hk2_t2 + di2l_rt2*rt2_t2
        di2_d2d = hk2_d2*di2l_hk2d + di2l_hk2*hk2_d2d
        di2_d2 = di2l_hk2*hk2_d2
        di2_msd = hk2_ms*di2l_hk2d + di2l_hk2*hk2_msd + rt2_ms*di2l_rt2d&
&         + di2l_rt2*rt2_msd
        di2_ms = di2l_hk2*hk2_ms + di2l_rt2*rt2_ms
        di2_red = rt2_re*di2l_rt2d + di2l_rt2*rt2_red
        di2_re = di2l_rt2*rt2_re
        di2_s2d = 0.0_8
      END IF
    END IF
!
!C----- add on CD contribution of inner shear layer
!       IF(ITYP.EQ.3 .AND. DW2.GT.0.0) THEN
!        DKON = 0.03*0.75**3
!        DDI = DKON*US2**3
!        DDI_US2 = 3.0*DKON*US2**2
!        DI2 = DI2 + DDI * DW2/DWTE
!        DI2_U2 = DI2_U2 + DDI_US2*US2_U2 * DW2/DWTE
!        DI2_T2 = DI2_T2 + DDI_US2*US2_T2 * DW2/DWTE
!        DI2_D2 = DI2_D2 + DDI_US2*US2_D2 * DW2/DWTE
!        DI2_MS = DI2_MS + DDI_US2*US2_MS * DW2/DWTE
!        DI2_RE = DI2_RE + DDI_US2*US2_RE * DW2/DWTE
!       ENDIF
!
    IF (ityp .EQ. 3) THEN
!------ laminar wake CD
      CALL DILW_D(hk2, hk2d, rt2, rt2d, di2l, di2ld, di2l_hk2, di2l_hk2d&
&           , di2l_rt2, di2l_rt2d)
! if (di2l>DI2) then
      IF (di2l .GT. di2r) THEN
!c        IF(.true.) THEN
!------- laminar wake CD is greater than turbulent CD -- use laminar
!-       (this will only occur for unreasonably small Rtheta)
!cc         write(*,*) 'CDt CDl Rt Hk:', DI2, DI2L, RT2, HK2
        di2d = di2ld
        di2 = di2l
        di2_s2 = 0.
        di2_u2d = hk2_u2*di2l_hk2d + di2l_hk2*hk2_u2d + rt2_u2*di2l_rt2d&
&         + di2l_rt2*rt2_u2d
        di2_u2 = di2l_hk2*hk2_u2 + di2l_rt2*rt2_u2
        di2_t2d = hk2_t2*di2l_hk2d + di2l_hk2*hk2_t2d + rt2_t2*di2l_rt2d&
&         + di2l_rt2*rt2_t2d
        di2_t2 = di2l_hk2*hk2_t2 + di2l_rt2*rt2_t2
        di2_d2d = hk2_d2*di2l_hk2d + di2l_hk2*hk2_d2d
        di2_d2 = di2l_hk2*hk2_d2
        di2_msd = hk2_ms*di2l_hk2d + di2l_hk2*hk2_msd + rt2_ms*di2l_rt2d&
&         + di2l_rt2*rt2_msd
        di2_ms = di2l_hk2*hk2_ms + di2l_rt2*rt2_ms
        di2_red = rt2_re*di2l_rt2d + di2l_rt2*rt2_red
        di2_re = di2l_rt2*rt2_re
        di2_s2d = 0.0_8
      END IF
    END IF
!
!
    IF (ityp .EQ. 3) THEN
!----- double dissipation for the wake (two wake halves)
      di2d = 2.0*di2d
      di2 = di2*2.0
      di2_s2d = 2.0*di2_s2d
      di2_s2 = di2_s2*2.0
      di2_u2d = 2.0*di2_u2d
      di2_u2 = di2_u2*2.0
      di2_t2d = 2.0*di2_t2d
      di2_t2 = di2_t2*2.0
      di2_d2d = 2.0*di2_d2d
      di2_d2 = di2_d2*2.0
      di2_msd = 2.0*di2_msd
      di2_ms = di2_ms*2.0
      di2_red = 2.0*di2_red
      di2_re = di2_re*2.0
    END IF
!
!---- BL thickness (Delta) from simplified Green's correlation
    temp10 = 1.72/(hk2-1.0)
    de2d = (temp10+3.15)*t2d - t2*temp10*hk2d/(hk2-1.0) + d2d
    de2 = (temp10+3.15)*t2 + d2
    temp10 = t2/((hk2-1.0)*(hk2-1.0))
    de2_hk2d = -(1.72*(t2d-temp10*2*(hk2-1.0)*hk2d)/(hk2-1.0)**2)
    de2_hk2 = -(1.72*temp10)
!
    de2_u2d = hk2_u2*de2_hk2d + de2_hk2*hk2_u2d
    de2_u2 = de2_hk2*hk2_u2
    de2_t2d = hk2_t2*de2_hk2d + de2_hk2*hk2_t2d - 1.72*hk2d/(hk2-1.0)**2
    de2_t2 = de2_hk2*hk2_t2 + (3.15+1.72/(hk2-1.0))
    de2_d2d = hk2_d2*de2_hk2d + de2_hk2*hk2_d2d
    de2_d2 = de2_hk2*hk2_d2 + 1.0
    de2_msd = hk2_ms*de2_hk2d + de2_hk2*hk2_msd
    de2_ms = de2_hk2*hk2_ms
!
!cc      HDMAX = 15.0
    hdmax = 12.0
    de2r = de2
    t2r = t2
! if (DE2>hdmax * T2) then
    IF (de2r .GT. hdmax*t2r) THEN
!ccc      IF(DE2 .GT. HDMAX*T2 .AND. (HK2 .GT. 4.0 .OR. ITYP.EQ.3)) THEN
      de2d = hdmax*t2d
      de2 = hdmax*t2
      de2_u2 = 0.0
      de2_t2 = hdmax
      de2_d2 = 0.0
      de2_ms = 0.0
      de2_t2d = 0.0_8
      de2_d2d = 0.0_8
      de2_u2d = 0.0_8
      de2_msd = 0.0_8
    END IF
  END SUBROUTINE BLVAR_D

!*==BLVAR.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
! BLKIN
