!----------------------------------------------------
!     Calculates all secondary "2" variables from
!     the primary "2" variables X2, U2, T2, D2, S2.
!     Also calculates the sensitivities of the
!     secondary variables wrt the primary variables.
!
!      ITYP = 1 :  laminar
!      ITYP = 2 :  turbulent
!      ITYP = 3 :  turbulent wake
!----------------------------------------------------
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    INTEGER :: ityp
! intent (in) Ityp
!
! Local variables
!
    REAL :: cf2l, cf2l_hk2, cf2l_m2, cf2l_rt2, cf2t, cf2t_d2, cf2t_hk2, &
&   cf2t_m2, cf2t_ms, cf2t_re, cf2t_rt2, cf2t_t2, cf2t_u2, cf2_hk2, &
&   cf2_m2, cf2_rt2, cq2_h2, cq2_hk2, cq2_hs2, cq2_rt2, cq2_us2, dd, &
&   dd_hs2, dd_rt2, dd_s2, dd_us2, de2_hk2, dfac, df_fl, df_hk2, df_rt2&
&   , di2l, di2l_hk2, di2l_rt2, di2_cf2t, di2_hk2, di2_hs2, di2_rt2, &
&   di2_us2, fl, fl_hk2, fl_rt2, gcc, grt, hc2_hk2, hc2_m2, hdmax, hkb, &
&   hkc, hkc_hk2, hkc_rt2, hmin, hm_rt2, hs2_hk2, hs2_m2, hs2_rt2, tfl, &
&   us2_h2, us2_hk2, us2_hs2, usb
    REAL :: us2r, cf2r, di2r, de2r, t2r
    INTRINSIC MAX
    INTRINSIC SQRT
    INTRINSIC LOG
