    REAL, DIMENSION(4) :: blm, blr, blrez, blx, btm, btr, btrez, btx
    REAL, DIMENSION(4) :: blmd, blrd, blrezd, blxd, btmd, btrd, btrezd, &
&   btxd
    REAL :: ctr, ctr_hk2, dt, dt_a1, dt_d1, dt_d2, dt_ms, dt_re, dt_t1, &
