&   , ut_re, ut_t1, ut_t2, ut_u1, ut_u2, ut_x1, ut_x2, ut_xf, wf1, &
&   wf1_a1, wf1_d1, wf1_d2, wf1_ms, wf1_re, wf1_t1, wf1_t2, wf1_u1, &
&   wf1_u2, wf1_x1, wf1_x2, wf1_xf, wf2, wf2_a1, wf2_d1, wf2_d2, wf2_ms&
&   , wf2_re, wf2_t1, wf2_t2
    REAL :: wf2_u1, wf2_u2
    REAL :: ctrd, ctr_hk2d, dtd, dt_a1d, dt_d1d, dt_d2d, dt_msd, dt_red&
&   , dt_t1d, dt_t2d, dt_u1d, dt_u2d, dt_x1d, dt_x2d, dt_xfd, std, &
&   st_a1d, st_d1d, st_d2d, st_dtd, st_msd, st_red, st_t1d, st_t2d, &
&   st_ttd, st_u1d, st_u2d, st_utd, st_x1d, st_x2d, st_xfd, ttd, tt_a1d&
&   , tt_d1d, tt_d2d, tt_msd, tt_red, tt_t1d, tt_t2d, tt_u1d, tt_u2d, &
&   tt_x1d, tt_x2d, tt_xfd, utd, ut_a1d, ut_d1d, ut_d2d, ut_msd, ut_red&
&   , ut_t1d, ut_t2d, ut_u1d, ut_u2d, ut_x1d, ut_x2d, ut_xfd, wf1d, &
&   wf1_a1d, wf1_d1d, wf1_d2d, wf1_msd, wf1_red, wf1_t1d, wf1_t2d, &
&   wf1_u1d, wf1_u2d, wf1_x1d, wf1_x2d, wf1_xfd, wf2d, wf2_a1d, wf2_d1d&
&   , wf2_d2d, wf2_msd, wf2_red, wf2_t1d, wf2_t2d
    REAL :: wf2_u1d, wf2_u2d
