!
!
!---- save variables and sensitivities for future restoration
    CALL BLC_SAVE1_D()
    CALL BLC_SAVE2_D()
!
!---- weighting factors for linear interpolation to transition point
    temp = (xt-x1)/(x2-x1)
    wf2d = (xtd-x1d-temp*(x2d-x1d))/(x2-x1)
    wf2 = temp
    temp = 1.0/(x2-x1)
    wf2_xtd = -(temp*(x2d-x1d)/(x2-x1))
    wf2_xt = temp
!
    wf2_a1d = xt_a1*wf2_xtd + wf2_xt*xt_a1d
    wf2_a1 = wf2_xt*xt_a1
    temp = (wf2-1.0)/(x2-x1)
    wf2_x1d = xt_x1*wf2_xtd + wf2_xt*xt_x1d + (wf2d-temp*(x2d-x1d))/(x2-&
&     x1)
    wf2_x1 = wf2_xt*xt_x1 + temp
    temp = wf2/(x2-x1)
    wf2_x2d = xt_x2*wf2_xtd + wf2_xt*xt_x2d - (wf2d-temp*(x2d-x1d))/(x2-&
&     x1)
    wf2_x2 = wf2_xt*xt_x2 - temp
    wf2_t1d = xt_t1*wf2_xtd + wf2_xt*xt_t1d
    wf2_t1 = wf2_xt*xt_t1
    wf2_t2d = xt_t2*wf2_xtd + wf2_xt*xt_t2d
    wf2_t2 = wf2_xt*xt_t2
    wf2_d1d = xt_d1*wf2_xtd + wf2_xt*xt_d1d
    wf2_d1 = wf2_xt*xt_d1
    wf2_d2d = xt_d2*wf2_xtd + wf2_xt*xt_d2d
    wf2_d2 = wf2_xt*xt_d2
    wf2_u1d = xt_u1*wf2_xtd + wf2_xt*xt_u1d
    wf2_u1 = wf2_xt*xt_u1
    wf2_u2d = xt_u2*wf2_xtd + wf2_xt*xt_u2d
    wf2_u2 = wf2_xt*xt_u2
    wf2_msd = xt_ms*wf2_xtd + wf2_xt*xt_msd
    wf2_ms = wf2_xt*xt_ms
    wf2_red = xt_re*wf2_xtd + wf2_xt*xt_red
    wf2_re = wf2_xt*xt_re
    wf2_xfd = xt_xf*wf2_xtd
    wf2_xf = wf2_xt*xt_xf
!
    wf1d = -wf2d
    wf1 = 1.0 - wf2
    wf1_a1d = -wf2_a1d
    wf1_a1 = -wf2_a1
    wf1_x1d = -wf2_x1d
    wf1_x1 = -wf2_x1
    wf1_x2d = -wf2_x2d
    wf1_x2 = -wf2_x2
    wf1_t1d = -wf2_t1d
    wf1_t1 = -wf2_t1
    wf1_t2d = -wf2_t2d
    wf1_t2 = -wf2_t2
    wf1_d1d = -wf2_d1d
    wf1_d1 = -wf2_d1
    wf1_d2d = -wf2_d2d
    wf1_d2 = -wf2_d2
    wf1_u1d = -wf2_u1d
    wf1_u1 = -wf2_u1
    wf1_u2d = -wf2_u2d
    wf1_u2 = -wf2_u2
    wf1_msd = -wf2_msd
    wf1_ms = -wf2_ms
    wf1_red = -wf2_red
    wf1_re = -wf2_re
    wf1_xfd = -wf2_xfd
    wf1_xf = -wf2_xf
!
!
!**** FIRST,  do laminar part between X1 and XT
!
!-----interpolate primary variables to transition point
    ttd = wf1*t1d + t1*wf1d + wf2*t2d + t2*wf2d
    tt = t1*wf1 + t2*wf2
    tt_a1d = wf1_a1*t1d + t1*wf1_a1d + wf2_a1*t2d + t2*wf2_a1d
    tt_a1 = t1*wf1_a1 + t2*wf2_a1
    tt_x1d = wf1_x1*t1d + t1*wf1_x1d + wf2_x1*t2d + t2*wf2_x1d
    tt_x1 = t1*wf1_x1 + t2*wf2_x1
    tt_x2d = wf1_x2*t1d + t1*wf1_x2d + wf2_x2*t2d + t2*wf2_x2d
    tt_x2 = t1*wf1_x2 + t2*wf2_x2
    tt_t1d = wf1_t1*t1d + t1*wf1_t1d + wf2_t1*t2d + t2*wf2_t1d + wf1d
    tt_t1 = t1*wf1_t1 + t2*wf2_t1 + wf1
    tt_t2d = wf1_t2*t1d + t1*wf1_t2d + wf2_t2*t2d + t2*wf2_t2d + wf2d
    tt_t2 = t1*wf1_t2 + t2*wf2_t2 + wf2
    tt_d1d = wf1_d1*t1d + t1*wf1_d1d + wf2_d1*t2d + t2*wf2_d1d
    tt_d1 = t1*wf1_d1 + t2*wf2_d1
    tt_d2d = wf1_d2*t1d + t1*wf1_d2d + wf2_d2*t2d + t2*wf2_d2d
    tt_d2 = t1*wf1_d2 + t2*wf2_d2
    tt_u1d = wf1_u1*t1d + t1*wf1_u1d + wf2_u1*t2d + t2*wf2_u1d
    tt_u1 = t1*wf1_u1 + t2*wf2_u1
    tt_u2d = wf1_u2*t1d + t1*wf1_u2d + wf2_u2*t2d + t2*wf2_u2d
    tt_u2 = t1*wf1_u2 + t2*wf2_u2
    tt_msd = wf1_ms*t1d + t1*wf1_msd + wf2_ms*t2d + t2*wf2_msd
    tt_ms = t1*wf1_ms + t2*wf2_ms
    tt_red = wf1_re*t1d + t1*wf1_red + wf2_re*t2d + t2*wf2_red
    tt_re = t1*wf1_re + t2*wf2_re
    tt_xfd = wf1_xf*t1d + t1*wf1_xfd + wf2_xf*t2d + t2*wf2_xfd
    tt_xf = t1*wf1_xf + t2*wf2_xf
!
    dtd = wf1*d1d + d1*wf1d + wf2*d2d + d2*wf2d
    dt = d1*wf1 + d2*wf2
    dt_a1d = wf1_a1*d1d + d1*wf1_a1d + wf2_a1*d2d + d2*wf2_a1d
    dt_a1 = d1*wf1_a1 + d2*wf2_a1
    dt_x1d = wf1_x1*d1d + d1*wf1_x1d + wf2_x1*d2d + d2*wf2_x1d
    dt_x1 = d1*wf1_x1 + d2*wf2_x1
    dt_x2d = wf1_x2*d1d + d1*wf1_x2d + wf2_x2*d2d + d2*wf2_x2d
    dt_x2 = d1*wf1_x2 + d2*wf2_x2
    dt_t1d = wf1_t1*d1d + d1*wf1_t1d + wf2_t1*d2d + d2*wf2_t1d
    dt_t1 = d1*wf1_t1 + d2*wf2_t1
    dt_t2d = wf1_t2*d1d + d1*wf1_t2d + wf2_t2*d2d + d2*wf2_t2d
    dt_t2 = d1*wf1_t2 + d2*wf2_t2
    dt_d1d = wf1_d1*d1d + d1*wf1_d1d + wf2_d1*d2d + d2*wf2_d1d + wf1d
    dt_d1 = d1*wf1_d1 + d2*wf2_d1 + wf1
    dt_d2d = wf1_d2*d1d + d1*wf1_d2d + wf2_d2*d2d + d2*wf2_d2d + wf2d
    dt_d2 = d1*wf1_d2 + d2*wf2_d2 + wf2
    dt_u1d = wf1_u1*d1d + d1*wf1_u1d + wf2_u1*d2d + d2*wf2_u1d
    dt_u1 = d1*wf1_u1 + d2*wf2_u1
    dt_u2d = wf1_u2*d1d + d1*wf1_u2d + wf2_u2*d2d + d2*wf2_u2d
    dt_u2 = d1*wf1_u2 + d2*wf2_u2
    dt_msd = wf1_ms*d1d + d1*wf1_msd + wf2_ms*d2d + d2*wf2_msd
    dt_ms = d1*wf1_ms + d2*wf2_ms
    dt_red = wf1_re*d1d + d1*wf1_red + wf2_re*d2d + d2*wf2_red
    dt_re = d1*wf1_re + d2*wf2_re
    dt_xfd = wf1_xf*d1d + d1*wf1_xfd + wf2_xf*d2d + d2*wf2_xfd
    dt_xf = d1*wf1_xf + d2*wf2_xf
!
    utd = wf1*u1d + u1*wf1d + wf2*u2d + u2*wf2d
    ut = u1*wf1 + u2*wf2
    ut_a1d = wf1_a1*u1d + u1*wf1_a1d + wf2_a1*u2d + u2*wf2_a1d
    ut_a1 = u1*wf1_a1 + u2*wf2_a1
    ut_x1d = wf1_x1*u1d + u1*wf1_x1d + wf2_x1*u2d + u2*wf2_x1d
    ut_x1 = u1*wf1_x1 + u2*wf2_x1
    ut_x2d = wf1_x2*u1d + u1*wf1_x2d + wf2_x2*u2d + u2*wf2_x2d
    ut_x2 = u1*wf1_x2 + u2*wf2_x2
    ut_t1d = wf1_t1*u1d + u1*wf1_t1d + wf2_t1*u2d + u2*wf2_t1d
    ut_t1 = u1*wf1_t1 + u2*wf2_t1
    ut_t2d = wf1_t2*u1d + u1*wf1_t2d + wf2_t2*u2d + u2*wf2_t2d
    ut_t2 = u1*wf1_t2 + u2*wf2_t2
    ut_d1d = wf1_d1*u1d + u1*wf1_d1d + wf2_d1*u2d + u2*wf2_d1d
    ut_d1 = u1*wf1_d1 + u2*wf2_d1
    ut_d2d = wf1_d2*u1d + u1*wf1_d2d + wf2_d2*u2d + u2*wf2_d2d
    ut_d2 = u1*wf1_d2 + u2*wf2_d2
    ut_u1d = wf1_u1*u1d + u1*wf1_u1d + wf2_u1*u2d + u2*wf2_u1d + wf1d
    ut_u1 = u1*wf1_u1 + u2*wf2_u1 + wf1
    ut_u2d = wf1_u2*u1d + u1*wf1_u2d + wf2_u2*u2d + u2*wf2_u2d + wf2d
    ut_u2 = u1*wf1_u2 + u2*wf2_u2 + wf2
    ut_msd = wf1_ms*u1d + u1*wf1_msd + wf2_ms*u2d + u2*wf2_msd
    ut_ms = u1*wf1_ms + u2*wf2_ms
    ut_red = wf1_re*u1d + u1*wf1_red + wf2_re*u2d + u2*wf2_red
    ut_re = u1*wf1_re + u2*wf2_re
    ut_xfd = wf1_xf*u1d + u1*wf1_xfd + wf2_xf*u2d + u2*wf2_xfd
    ut_xf = u1*wf1_xf + u2*wf2_xf
!
!---- set primary "T" variables at XT  (really placed into "2" variables)
    x2d = xtd
    x2 = xt
    t2d = ttd
    t2 = tt
    d2d = dtd
    d2 = dt
    u2d = utd
    u2 = ut
!
    ampl2d = amcritd
    ampl2 = amcrit
    s2 = 0.
!
!---- calculate laminar secondary "T" variables
    CALL BLKIN_D()
    s2d = 0.0_8
    CALL BLVAR_D(1)
!
!---- calculate X1-XT midpoint CFM value
    CALL BLMID_D(1)
!=
!=    at this point, all "2" variables are really "T" variables at XT
!=
!
!---- set up Newton system for dAm, dTh, dDs, dUe, dXi  at  X1 and XT
    s2d = 0.0_8
    CALL BLDIF_D(1)
    blmd = 0.0_8
    blrd = 0.0_8
    blxd = 0.0_8
    bl1d = 0.0_8
    bl2d = 0.0_8
    blrezd = 0.0_8
!
!---- The current Newton system is in terms of "1" and "T" variables,
!-    so calculate its equivalent in terms of "1" and "2" variables.
!-    In other words, convert residual sensitivities wrt "T" variables
!-    into sensitivities wrt "1" and "2" variables.  The amplification
!-    equation is unnecessary here, so the K=1 row is left empty.
    DO k=2,3
      blrezd(k) = vsrezd(k)
      blrez(k) = vsrez(k)
      blmd(k) = vsmd(k) + tt_ms*vs2d(k, 2) + vs2(k, 2)*tt_msd + dt_ms*&
&       vs2d(k, 3) + vs2(k, 3)*dt_msd + ut_ms*vs2d(k, 4) + vs2(k, 4)*&
&       ut_msd + xt_ms*vs2d(k, 5) + vs2(k, 5)*xt_msd
      blm(k) = vsm(k) + vs2(k, 2)*tt_ms + vs2(k, 3)*dt_ms + vs2(k, 4)*&
&       ut_ms + vs2(k, 5)*xt_ms
      blrd(k) = vsrd(k) + tt_re*vs2d(k, 2) + vs2(k, 2)*tt_red + dt_re*&
&       vs2d(k, 3) + vs2(k, 3)*dt_red + ut_re*vs2d(k, 4) + vs2(k, 4)*&
&       ut_red + xt_re*vs2d(k, 5) + vs2(k, 5)*xt_red
      blr(k) = vsr(k) + vs2(k, 2)*tt_re + vs2(k, 3)*dt_re + vs2(k, 4)*&
&       ut_re + vs2(k, 5)*xt_re
      blxd(k) = vsxd(k) + tt_xf*vs2d(k, 2) + vs2(k, 2)*tt_xfd + dt_xf*&
&       vs2d(k, 3) + vs2(k, 3)*dt_xfd + ut_xf*vs2d(k, 4) + vs2(k, 4)*&
&       ut_xfd + xt_xf*vs2d(k, 5)
      blx(k) = vsx(k) + vs2(k, 2)*tt_xf + vs2(k, 3)*dt_xf + vs2(k, 4)*&
&       ut_xf + vs2(k, 5)*xt_xf
!
      bl1d(k, 1) = vs1d(k, 1) + tt_a1*vs2d(k, 2) + vs2(k, 2)*tt_a1d + &
&       dt_a1*vs2d(k, 3) + vs2(k, 3)*dt_a1d + ut_a1*vs2d(k, 4) + vs2(k, &
&       4)*ut_a1d + xt_a1*vs2d(k, 5) + vs2(k, 5)*xt_a1d
      bl1(k, 1) = vs1(k, 1) + vs2(k, 2)*tt_a1 + vs2(k, 3)*dt_a1 + vs2(k&
&       , 4)*ut_a1 + vs2(k, 5)*xt_a1
      bl1d(k, 2) = vs1d(k, 2) + tt_t1*vs2d(k, 2) + vs2(k, 2)*tt_t1d + &
&       dt_t1*vs2d(k, 3) + vs2(k, 3)*dt_t1d + ut_t1*vs2d(k, 4) + vs2(k, &
&       4)*ut_t1d + xt_t1*vs2d(k, 5) + vs2(k, 5)*xt_t1d
      bl1(k, 2) = vs1(k, 2) + vs2(k, 2)*tt_t1 + vs2(k, 3)*dt_t1 + vs2(k&
&       , 4)*ut_t1 + vs2(k, 5)*xt_t1
      bl1d(k, 3) = vs1d(k, 3) + tt_d1*vs2d(k, 2) + vs2(k, 2)*tt_d1d + &
&       dt_d1*vs2d(k, 3) + vs2(k, 3)*dt_d1d + ut_d1*vs2d(k, 4) + vs2(k, &
&       4)*ut_d1d + xt_d1*vs2d(k, 5) + vs2(k, 5)*xt_d1d
      bl1(k, 3) = vs1(k, 3) + vs2(k, 2)*tt_d1 + vs2(k, 3)*dt_d1 + vs2(k&
&       , 4)*ut_d1 + vs2(k, 5)*xt_d1
      bl1d(k, 4) = vs1d(k, 4) + tt_u1*vs2d(k, 2) + vs2(k, 2)*tt_u1d + &
&       dt_u1*vs2d(k, 3) + vs2(k, 3)*dt_u1d + ut_u1*vs2d(k, 4) + vs2(k, &
&       4)*ut_u1d + xt_u1*vs2d(k, 5) + vs2(k, 5)*xt_u1d
      bl1(k, 4) = vs1(k, 4) + vs2(k, 2)*tt_u1 + vs2(k, 3)*dt_u1 + vs2(k&
&       , 4)*ut_u1 + vs2(k, 5)*xt_u1
      bl1d(k, 5) = vs1d(k, 5) + tt_x1*vs2d(k, 2) + vs2(k, 2)*tt_x1d + &
&       dt_x1*vs2d(k, 3) + vs2(k, 3)*dt_x1d + ut_x1*vs2d(k, 4) + vs2(k, &
&       4)*ut_x1d + xt_x1*vs2d(k, 5) + vs2(k, 5)*xt_x1d
      bl1(k, 5) = vs1(k, 5) + vs2(k, 2)*tt_x1 + vs2(k, 3)*dt_x1 + vs2(k&
&       , 4)*ut_x1 + vs2(k, 5)*xt_x1
!
      bl2d(k, 1) = 0.0_8
      bl2(k, 1) = 0.
      bl2d(k, 2) = tt_t2*vs2d(k, 2) + vs2(k, 2)*tt_t2d + dt_t2*vs2d(k, 3&
&       ) + vs2(k, 3)*dt_t2d + ut_t2*vs2d(k, 4) + vs2(k, 4)*ut_t2d + &
&       xt_t2*vs2d(k, 5) + vs2(k, 5)*xt_t2d
      bl2(k, 2) = vs2(k, 2)*tt_t2 + vs2(k, 3)*dt_t2 + vs2(k, 4)*ut_t2 + &
&       vs2(k, 5)*xt_t2
      bl2d(k, 3) = tt_d2*vs2d(k, 2) + vs2(k, 2)*tt_d2d + dt_d2*vs2d(k, 3&
&       ) + vs2(k, 3)*dt_d2d + ut_d2*vs2d(k, 4) + vs2(k, 4)*ut_d2d + &
&       xt_d2*vs2d(k, 5) + vs2(k, 5)*xt_d2d
      bl2(k, 3) = vs2(k, 2)*tt_d2 + vs2(k, 3)*dt_d2 + vs2(k, 4)*ut_d2 + &
&       vs2(k, 5)*xt_d2
      bl2d(k, 4) = tt_u2*vs2d(k, 2) + vs2(k, 2)*tt_u2d + dt_u2*vs2d(k, 3&
&       ) + vs2(k, 3)*dt_u2d + ut_u2*vs2d(k, 4) + vs2(k, 4)*ut_u2d + &
&       xt_u2*vs2d(k, 5) + vs2(k, 5)*xt_u2d
      bl2(k, 4) = vs2(k, 2)*tt_u2 + vs2(k, 3)*dt_u2 + vs2(k, 4)*ut_u2 + &
&       vs2(k, 5)*xt_u2
      bl2d(k, 5) = tt_x2*vs2d(k, 2) + vs2(k, 2)*tt_x2d + dt_x2*vs2d(k, 3&
&       ) + vs2(k, 3)*dt_x2d + ut_x2*vs2d(k, 4) + vs2(k, 4)*ut_x2d + &
&       xt_x2*vs2d(k, 5) + vs2(k, 5)*xt_x2d
      bl2(k, 5) = vs2(k, 2)*tt_x2 + vs2(k, 3)*dt_x2 + vs2(k, 4)*ut_x2 + &
&       vs2(k, 5)*xt_x2
    END DO
!
!
!
!**** SECOND, set up turbulent part between XT and X2  ****
!
!---- calculate equilibrium shear coefficient CQT at transition point
    s2d = 0.0_8
    CALL BLVAR_D(2)
!
!---- set initial shear coefficient value ST at transition point
!-    ( note that CQ2, CQ2_T2, etc. are really "CQT", "CQT_TT", etc.)
!
    temp = ctrcex/(hk2-1.0)
    ctrd = ctrcon*EXP(-temp)*temp*hk2d/(hk2-1.0)
    ctr = ctrcon*EXP(-temp)
    temp = ctr/((hk2-1.0)*(hk2-1.0))
    ctr_hk2d = ctrcex*(ctrd-temp*2*(hk2-1.0)*hk2d)/(hk2-1.0)**2
    ctr_hk2 = ctrcex*temp
!
!      CTR     = 1.1*EXP(-10.0/HK2**2)
!      CTR_HK2 = CTR * 10.0 * 2.0/HK2**3
!
!CC      CTR = 1.2
!CC      CTR = 0.7
!CC      CTR_HK2 = 0.0
!
    std = cq2*ctrd + ctr*cq2d
    st = ctr*cq2
    st_ttd = cq2_t2*ctrd + ctr*cq2_t2d + hk2_t2*(ctr_hk2*cq2d+cq2*&
&     ctr_hk2d) + cq2*ctr_hk2*hk2_t2d
    st_tt = ctr*cq2_t2 + cq2*ctr_hk2*hk2_t2
    st_dtd = cq2_d2*ctrd + ctr*cq2_d2d + hk2_d2*(ctr_hk2*cq2d+cq2*&
&     ctr_hk2d) + cq2*ctr_hk2*hk2_d2d
    st_dt = ctr*cq2_d2 + cq2*ctr_hk2*hk2_d2
    st_utd = cq2_u2*ctrd + ctr*cq2_u2d + hk2_u2*(ctr_hk2*cq2d+cq2*&
&     ctr_hk2d) + cq2*ctr_hk2*hk2_u2d
    st_ut = ctr*cq2_u2 + cq2*ctr_hk2*hk2_u2
    st_msd = cq2_ms*ctrd + ctr*cq2_msd + hk2_ms*(ctr_hk2*cq2d+cq2*&
&     ctr_hk2d) + cq2*ctr_hk2*hk2_msd
    st_ms = ctr*cq2_ms + cq2*ctr_hk2*hk2_ms
    st_red = cq2_re*ctrd + ctr*cq2_red
    st_re = ctr*cq2_re
!
!---- calculate ST sensitivities wrt the actual "1" and "2" variables
    st_a1d = tt_a1*st_ttd + st_tt*tt_a1d + dt_a1*st_dtd + st_dt*dt_a1d +&
&     ut_a1*st_utd + st_ut*ut_a1d
    st_a1 = st_tt*tt_a1 + st_dt*dt_a1 + st_ut*ut_a1
    st_x1d = tt_x1*st_ttd + st_tt*tt_x1d + dt_x1*st_dtd + st_dt*dt_x1d +&
&     ut_x1*st_utd + st_ut*ut_x1d
    st_x1 = st_tt*tt_x1 + st_dt*dt_x1 + st_ut*ut_x1
    st_x2d = tt_x2*st_ttd + st_tt*tt_x2d + dt_x2*st_dtd + st_dt*dt_x2d +&
&     ut_x2*st_utd + st_ut*ut_x2d
    st_x2 = st_tt*tt_x2 + st_dt*dt_x2 + st_ut*ut_x2
    st_t1d = tt_t1*st_ttd + st_tt*tt_t1d + dt_t1*st_dtd + st_dt*dt_t1d +&
&     ut_t1*st_utd + st_ut*ut_t1d
    st_t1 = st_tt*tt_t1 + st_dt*dt_t1 + st_ut*ut_t1
    st_t2d = tt_t2*st_ttd + st_tt*tt_t2d + dt_t2*st_dtd + st_dt*dt_t2d +&
&     ut_t2*st_utd + st_ut*ut_t2d
    st_t2 = st_tt*tt_t2 + st_dt*dt_t2 + st_ut*ut_t2
    st_d1d = tt_d1*st_ttd + st_tt*tt_d1d + dt_d1*st_dtd + st_dt*dt_d1d +&
&     ut_d1*st_utd + st_ut*ut_d1d
    st_d1 = st_tt*tt_d1 + st_dt*dt_d1 + st_ut*ut_d1
    st_d2d = tt_d2*st_ttd + st_tt*tt_d2d + dt_d2*st_dtd + st_dt*dt_d2d +&
&     ut_d2*st_utd + st_ut*ut_d2d
    st_d2 = st_tt*tt_d2 + st_dt*dt_d2 + st_ut*ut_d2
    st_u1d = tt_u1*st_ttd + st_tt*tt_u1d + dt_u1*st_dtd + st_dt*dt_u1d +&
&     ut_u1*st_utd + st_ut*ut_u1d
    st_u1 = st_tt*tt_u1 + st_dt*dt_u1 + st_ut*ut_u1
    st_u2d = tt_u2*st_ttd + st_tt*tt_u2d + dt_u2*st_dtd + st_dt*dt_u2d +&
&     ut_u2*st_utd + st_ut*ut_u2d
    st_u2 = st_tt*tt_u2 + st_dt*dt_u2 + st_ut*ut_u2
    st_msd = tt_ms*st_ttd + st_tt*tt_msd + dt_ms*st_dtd + st_dt*dt_msd +&
&     ut_ms*st_utd + st_ut*ut_msd + st_msd
    st_ms = st_tt*tt_ms + st_dt*dt_ms + st_ut*ut_ms + st_ms
    st_red = tt_re*st_ttd + st_tt*tt_red + dt_re*st_dtd + st_dt*dt_red +&
&     ut_re*st_utd + st_ut*ut_red + st_red
    st_re = st_tt*tt_re + st_dt*dt_re + st_ut*ut_re + st_re
    st_xfd = tt_xf*st_ttd + st_tt*tt_xfd + dt_xf*st_dtd + st_dt*dt_xfd +&
&     ut_xf*st_utd + st_ut*ut_xfd
    st_xf = st_tt*tt_xf + st_dt*dt_xf + st_ut*ut_xf
!
    ampl2 = 0.
    s2d = std
    s2 = st
!
!---- recalculate turbulent secondary "T" variables using proper CTI
    CALL BLVAR_D(2)
!
!---- set "1" variables to "T" variables and reset "2" variables
!-    to their saved turbulent values
    u2_msd = 0.0_8
    ampl2d = 0.0_8
    r2d = 0.0_8
    us2_red = 0.0_8
    v2_red = 0.0_8
    u2_ueid = 0.0_8
    r2_msd = 0.0_8
    v2_msd = 0.0_8
    r2_u2d = 0.0_8
    v2d = 0.0_8
    v2_u2d = 0.0_8
    CALL BLC_1FROM2_D()
    CALL BLC_RESTORE2_D()
!
!---- calculate XT-X2 midpoint CFM value
    CALL BLMID_D(2)
!
!---- set up Newton system for dCt, dTh, dDs, dUe, dXi  at  XT and X2
    ampl1d = 0.0_8
    CALL BLDIF_D(2)
    btrezd = 0.0_8
    bt1d = 0.0_8
    bt2d = 0.0_8
    btmd = 0.0_8
    btrd = 0.0_8
    btxd = 0.0_8
!
!---- convert sensitivities wrt "T" variables into sensitivities
!-    wrt "1" and "2" variables as done before for the laminar part
    DO k=1,3
      btrezd(k) = vsrezd(k)
      btrez(k) = vsrez(k)
      btmd(k) = vsmd(k) + st_ms*vs1d(k, 1) + vs1(k, 1)*st_msd + tt_ms*&
&       vs1d(k, 2) + vs1(k, 2)*tt_msd + dt_ms*vs1d(k, 3) + vs1(k, 3)*&
&       dt_msd + ut_ms*vs1d(k, 4) + vs1(k, 4)*ut_msd + xt_ms*vs1d(k, 5) &
&       + vs1(k, 5)*xt_msd
      btm(k) = vsm(k) + vs1(k, 1)*st_ms + vs1(k, 2)*tt_ms + vs1(k, 3)*&
