      btxd(k) = vsxd(k) + st_xf*vs1d(k, 1) + vs1(k, 1)*st_xfd + tt_xf*&
&       vs1d(k, 2) + vs1(k, 2)*tt_xfd + dt_xf*vs1d(k, 3) + vs1(k, 3)*&
&       dt_xfd + ut_xf*vs1d(k, 4) + vs1(k, 4)*ut_xfd + xt_xf*vs1d(k, 5)
      btx(k) = vsx(k) + vs1(k, 1)*st_xf + vs1(k, 2)*tt_xf + vs1(k, 3)*&
&       dt_xf + vs1(k, 4)*ut_xf + vs1(k, 5)*xt_xf
!
      bt1d(k, 1) = st_a1*vs1d(k, 1) + vs1(k, 1)*st_a1d + tt_a1*vs1d(k, 2&
&       ) + vs1(k, 2)*tt_a1d + dt_a1*vs1d(k, 3) + vs1(k, 3)*dt_a1d + &
&       ut_a1*vs1d(k, 4) + vs1(k, 4)*ut_a1d + xt_a1*vs1d(k, 5) + vs1(k, &
&       5)*xt_a1d
      bt1(k, 1) = vs1(k, 1)*st_a1 + vs1(k, 2)*tt_a1 + vs1(k, 3)*dt_a1 + &
&       vs1(k, 4)*ut_a1 + vs1(k, 5)*xt_a1
      bt1d(k, 2) = st_t1*vs1d(k, 1) + vs1(k, 1)*st_t1d + tt_t1*vs1d(k, 2&
&       ) + vs1(k, 2)*tt_t1d + dt_t1*vs1d(k, 3) + vs1(k, 3)*dt_t1d + &
&       ut_t1*vs1d(k, 4) + vs1(k, 4)*ut_t1d + xt_t1*vs1d(k, 5) + vs1(k, &
&       5)*xt_t1d
      bt1(k, 2) = vs1(k, 1)*st_t1 + vs1(k, 2)*tt_t1 + vs1(k, 3)*dt_t1 + &
&       vs1(k, 4)*ut_t1 + vs1(k, 5)*xt_t1
      bt1d(k, 3) = st_d1*vs1d(k, 1) + vs1(k, 1)*st_d1d + tt_d1*vs1d(k, 2&
&       ) + vs1(k, 2)*tt_d1d + dt_d1*vs1d(k, 3) + vs1(k, 3)*dt_d1d + &
&       ut_d1*vs1d(k, 4) + vs1(k, 4)*ut_d1d + xt_d1*vs1d(k, 5) + vs1(k, &
&       5)*xt_d1d
      bt1(k, 3) = vs1(k, 1)*st_d1 + vs1(k, 2)*tt_d1 + vs1(k, 3)*dt_d1 + &
&       vs1(k, 4)*ut_d1 + vs1(k, 5)*xt_d1
      bt1d(k, 4) = st_u1*vs1d(k, 1) + vs1(k, 1)*st_u1d + tt_u1*vs1d(k, 2&
&       ) + vs1(k, 2)*tt_u1d + dt_u1*vs1d(k, 3) + vs1(k, 3)*dt_u1d + &
&       ut_u1*vs1d(k, 4) + vs1(k, 4)*ut_u1d + xt_u1*vs1d(k, 5) + vs1(k, &
&       5)*xt_u1d
      bt1(k, 4) = vs1(k, 1)*st_u1 + vs1(k, 2)*tt_u1 + vs1(k, 3)*dt_u1 + &
&       vs1(k, 4)*ut_u1 + vs1(k, 5)*xt_u1
      bt1d(k, 5) = st_x1*vs1d(k, 1) + vs1(k, 1)*st_x1d + tt_x1*vs1d(k, 2&
&       ) + vs1(k, 2)*tt_x1d + dt_x1*vs1d(k, 3) + vs1(k, 3)*dt_x1d + &
&       ut_x1*vs1d(k, 4) + vs1(k, 4)*ut_x1d + xt_x1*vs1d(k, 5) + vs1(k, &
&       5)*xt_x1d
      bt1(k, 5) = vs1(k, 1)*st_x1 + vs1(k, 2)*tt_x1 + vs1(k, 3)*dt_x1 + &
&       vs1(k, 4)*ut_x1 + vs1(k, 5)*xt_x1
!
      bt2d(k, 1) = vs2d(k, 1)
      bt2(k, 1) = vs2(k, 1)
      bt2d(k, 2) = vs2d(k, 2) + st_t2*vs1d(k, 1) + vs1(k, 1)*st_t2d + &
&       tt_t2*vs1d(k, 2) + vs1(k, 2)*tt_t2d + dt_t2*vs1d(k, 3) + vs1(k, &
&       3)*dt_t2d + ut_t2*vs1d(k, 4) + vs1(k, 4)*ut_t2d + xt_t2*vs1d(k, &
&       5) + vs1(k, 5)*xt_t2d
      bt2(k, 2) = vs2(k, 2) + vs1(k, 1)*st_t2 + vs1(k, 2)*tt_t2 + vs1(k&
&       , 3)*dt_t2 + vs1(k, 4)*ut_t2 + vs1(k, 5)*xt_t2
      bt2d(k, 3) = vs2d(k, 3) + st_d2*vs1d(k, 1) + vs1(k, 1)*st_d2d + &
&       tt_d2*vs1d(k, 2) + vs1(k, 2)*tt_d2d + dt_d2*vs1d(k, 3) + vs1(k, &
&       3)*dt_d2d + ut_d2*vs1d(k, 4) + vs1(k, 4)*ut_d2d + xt_d2*vs1d(k, &
&       5) + vs1(k, 5)*xt_d2d
      bt2(k, 3) = vs2(k, 3) + vs1(k, 1)*st_d2 + vs1(k, 2)*tt_d2 + vs1(k&
&       , 3)*dt_d2 + vs1(k, 4)*ut_d2 + vs1(k, 5)*xt_d2
      bt2d(k, 4) = vs2d(k, 4) + st_u2*vs1d(k, 1) + vs1(k, 1)*st_u2d + &
&       tt_u2*vs1d(k, 2) + vs1(k, 2)*tt_u2d + dt_u2*vs1d(k, 3) + vs1(k, &
&       3)*dt_u2d + ut_u2*vs1d(k, 4) + vs1(k, 4)*ut_u2d + xt_u2*vs1d(k, &
&       5) + vs1(k, 5)*xt_u2d
      bt2(k, 4) = vs2(k, 4) + vs1(k, 1)*st_u2 + vs1(k, 2)*tt_u2 + vs1(k&
&       , 3)*dt_u2 + vs1(k, 4)*ut_u2 + vs1(k, 5)*xt_u2
      bt2d(k, 5) = vs2d(k, 5) + st_x2*vs1d(k, 1) + vs1(k, 1)*st_x2d + &
&       tt_x2*vs1d(k, 2) + vs1(k, 2)*tt_x2d + dt_x2*vs1d(k, 3) + vs1(k, &
&       3)*dt_x2d + ut_x2*vs1d(k, 4) + vs1(k, 4)*ut_x2d + xt_x2*vs1d(k, &
&       5) + vs1(k, 5)*xt_x2d
      bt2(k, 5) = vs2(k, 5) + vs1(k, 1)*st_x2 + vs1(k, 2)*tt_x2 + vs1(k&
&       , 3)*dt_x2 + vs1(k, 4)*ut_x2 + vs1(k, 5)*xt_x2
    END DO
!
!
!---- Add up laminar and turbulent parts to get final system
!-    in terms of honest-to-God "1" and "2" variables.
    vsrezd(1) = btrezd(1)
    vsrez(1) = btrez(1)
    vsrezd(2) = blrezd(2) + btrezd(2)
    vsrez(2) = blrez(2) + btrez(2)
    vsrezd(3) = blrezd(3) + btrezd(3)
    vsrez(3) = blrez(3) + btrez(3)
    vsmd(1) = btmd(1)
    vsm(1) = btm(1)
    vsmd(2) = blmd(2) + btmd(2)
    vsm(2) = blm(2) + btm(2)
    vsmd(3) = blmd(3) + btmd(3)
    vsm(3) = blm(3) + btm(3)
    vsrd(1) = btrd(1)
    vsr(1) = btr(1)
    vsrd(2) = blrd(2) + btrd(2)
    vsr(2) = blr(2) + btr(2)
    vsrd(3) = blrd(3) + btrd(3)
    vsr(3) = blr(3) + btr(3)
    vsxd(1) = btxd(1)
    vsx(1) = btx(1)
    vsxd(2) = blxd(2) + btxd(2)
    vsx(2) = blx(2) + btx(2)
    vsxd(3) = blxd(3) + btxd(3)
    vsx(3) = blx(3) + btx(3)
    DO l=1,5
      vs1d(1, l) = bt1d(1, l)
      vs1(1, l) = bt1(1, l)
      vs2d(1, l) = bt2d(1, l)
      vs2(1, l) = bt2(1, l)
      vs1d(2, l) = bl1d(2, l) + bt1d(2, l)
      vs1(2, l) = bl1(2, l) + bt1(2, l)
      vs2d(2, l) = bl2d(2, l) + bt2d(2, l)
      vs2(2, l) = bl2(2, l) + bt2(2, l)
      vs1d(3, l) = bl1d(3, l) + bt1d(3, l)
      vs1(3, l) = bl1(3, l) + bt1(3, l)
      vs2d(3, l) = bl2d(3, l) + bt2d(3, l)
      vs2(3, l) = bl2(3, l) + bt2(3, l)
    END DO
!
!---- To be sanitary, restore "1" quantities which got clobbered
!-    in all of the numerical gymnastics above.  The "2" variables
!-    were already restored for the XT-X2 differencing part.
    CALL BLC_RESTORE1_D()
  END SUBROUTINE TRDIF_D

!*==TRDIF.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
! BLMID
  SUBROUTINE TRDIF()
!-----------------------------------------------
!     Sets up the Newton system governing the
!     transition interval.  Equations governing
!     the  laminar  part  X1 < xi < XT  and
!     the turbulent part  XT < xi < X2
!     are simply summed.
!-----------------------------------------------
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL, DIMENSION(4, 5) :: bl1, bl2, bt1, bt2
    REAL, DIMENSION(4) :: blm, blr, blrez, blx, btm, btr, btrez, btx
    REAL :: ctr, ctr_hk2, dt, dt_a1, dt_d1, dt_d2, dt_ms, dt_re, dt_t1, &
&   dt_t2, dt_u1, dt_u2, dt_x1, dt_x2, dt_xf, st, st_a1, st_d1, st_d2, &
&   st_dt, st_ms, st_re, st_t1, st_t2, st_tt, st_u1, st_u2, st_ut, st_x1&
&   , st_x2, st_xf, tt, tt_a1, tt_d1, tt_d2, tt_ms, tt_re, tt_t1, tt_t2&
&   , tt_u1, tt_u2, tt_x1, tt_x2, tt_xf, ut, ut_a1, ut_d1, ut_d2, ut_ms&
&   , ut_re, ut_t1, ut_t2, ut_u1, ut_u2, ut_x1, ut_x2, ut_xf, wf1, &
&   wf1_a1, wf1_d1, wf1_d2, wf1_ms, wf1_re, wf1_t1, wf1_t2, wf1_u1, &
&   wf1_u2, wf1_x1, wf1_x2, wf1_xf, wf2, wf2_a1, wf2_d1, wf2_d2, wf2_ms&
&   , wf2_re, wf2_t1, wf2_t2
    REAL :: wf2_u1, wf2_u2
    INTEGER :: icom, k, l
    REAL :: wf2_x1, wf2_x2, wf2_xf, wf2_xt
    INTRINSIC EXP
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
!---- save variables and sensitivities for future restoration
    CALL BLC_SAVE1()
    CALL BLC_SAVE2()
!
!---- weighting factors for linear interpolation to transition point
    wf2 = (xt-x1)/(x2-x1)
    wf2_xt = 1.0/(x2-x1)
!
    wf2_a1 = wf2_xt*xt_a1
    wf2_x1 = wf2_xt*xt_x1 + (wf2-1.0)/(x2-x1)
    wf2_x2 = wf2_xt*xt_x2 - wf2/(x2-x1)
    wf2_t1 = wf2_xt*xt_t1
    wf2_t2 = wf2_xt*xt_t2
    wf2_d1 = wf2_xt*xt_d1
    wf2_d2 = wf2_xt*xt_d2
    wf2_u1 = wf2_xt*xt_u1
    wf2_u2 = wf2_xt*xt_u2
    wf2_ms = wf2_xt*xt_ms
    wf2_re = wf2_xt*xt_re
    wf2_xf = wf2_xt*xt_xf
!
    wf1 = 1.0 - wf2
    wf1_a1 = -wf2_a1
    wf1_x1 = -wf2_x1
    wf1_x2 = -wf2_x2
    wf1_t1 = -wf2_t1
    wf1_t2 = -wf2_t2
    wf1_d1 = -wf2_d1
    wf1_d2 = -wf2_d2
    wf1_u1 = -wf2_u1
    wf1_u2 = -wf2_u2
    wf1_ms = -wf2_ms
    wf1_re = -wf2_re
    wf1_xf = -wf2_xf
!
!
!**** FIRST,  do laminar part between X1 and XT
!
!-----interpolate primary variables to transition point
    tt = t1*wf1 + t2*wf2
    tt_a1 = t1*wf1_a1 + t2*wf2_a1
    tt_x1 = t1*wf1_x1 + t2*wf2_x1
    tt_x2 = t1*wf1_x2 + t2*wf2_x2
    tt_t1 = t1*wf1_t1 + t2*wf2_t1 + wf1
    tt_t2 = t1*wf1_t2 + t2*wf2_t2 + wf2
    tt_d1 = t1*wf1_d1 + t2*wf2_d1
    tt_d2 = t1*wf1_d2 + t2*wf2_d2
    tt_u1 = t1*wf1_u1 + t2*wf2_u1
    tt_u2 = t1*wf1_u2 + t2*wf2_u2
    tt_ms = t1*wf1_ms + t2*wf2_ms
    tt_re = t1*wf1_re + t2*wf2_re
    tt_xf = t1*wf1_xf + t2*wf2_xf
!
    dt = d1*wf1 + d2*wf2
    dt_a1 = d1*wf1_a1 + d2*wf2_a1
    dt_x1 = d1*wf1_x1 + d2*wf2_x1
    dt_x2 = d1*wf1_x2 + d2*wf2_x2
    dt_t1 = d1*wf1_t1 + d2*wf2_t1
    dt_t2 = d1*wf1_t2 + d2*wf2_t2
    dt_d1 = d1*wf1_d1 + d2*wf2_d1 + wf1
    dt_d2 = d1*wf1_d2 + d2*wf2_d2 + wf2
    dt_u1 = d1*wf1_u1 + d2*wf2_u1
    dt_u2 = d1*wf1_u2 + d2*wf2_u2
    dt_ms = d1*wf1_ms + d2*wf2_ms
    dt_re = d1*wf1_re + d2*wf2_re
    dt_xf = d1*wf1_xf + d2*wf2_xf
!
    ut = u1*wf1 + u2*wf2
    ut_a1 = u1*wf1_a1 + u2*wf2_a1
    ut_x1 = u1*wf1_x1 + u2*wf2_x1
    ut_x2 = u1*wf1_x2 + u2*wf2_x2
    ut_t1 = u1*wf1_t1 + u2*wf2_t1
    ut_t2 = u1*wf1_t2 + u2*wf2_t2
    ut_d1 = u1*wf1_d1 + u2*wf2_d1
    ut_d2 = u1*wf1_d2 + u2*wf2_d2
    ut_u1 = u1*wf1_u1 + u2*wf2_u1 + wf1
    ut_u2 = u1*wf1_u2 + u2*wf2_u2 + wf2
    ut_ms = u1*wf1_ms + u2*wf2_ms
    ut_re = u1*wf1_re + u2*wf2_re
    ut_xf = u1*wf1_xf + u2*wf2_xf
!
!---- set primary "T" variables at XT  (really placed into "2" variables)
    x2 = xt
    t2 = tt
    d2 = dt
    u2 = ut
!
    ampl2 = amcrit
    s2 = 0.
!
!---- calculate laminar secondary "T" variables
    CALL BLKIN()
    CALL BLVAR(1)
!
!---- calculate X1-XT midpoint CFM value
    CALL BLMID(1)
!=
!=    at this point, all "2" variables are really "T" variables at XT
!=
!
!---- set up Newton system for dAm, dTh, dDs, dUe, dXi  at  X1 and XT
    CALL BLDIF(1)
!
!---- The current Newton system is in terms of "1" and "T" variables,
!-    so calculate its equivalent in terms of "1" and "2" variables.
!-    In other words, convert residual sensitivities wrt "T" variables
!-    into sensitivities wrt "1" and "2" variables.  The amplification
!-    equation is unnecessary here, so the K=1 row is left empty.
    DO k=2,3
      blrez(k) = vsrez(k)
      blm(k) = vsm(k) + vs2(k, 2)*tt_ms + vs2(k, 3)*dt_ms + vs2(k, 4)*&
&       ut_ms + vs2(k, 5)*xt_ms
      blr(k) = vsr(k) + vs2(k, 2)*tt_re + vs2(k, 3)*dt_re + vs2(k, 4)*&
&       ut_re + vs2(k, 5)*xt_re
      blx(k) = vsx(k) + vs2(k, 2)*tt_xf + vs2(k, 3)*dt_xf + vs2(k, 4)*&
&       ut_xf + vs2(k, 5)*xt_xf
!
      bl1(k, 1) = vs1(k, 1) + vs2(k, 2)*tt_a1 + vs2(k, 3)*dt_a1 + vs2(k&
&       , 4)*ut_a1 + vs2(k, 5)*xt_a1
      bl1(k, 2) = vs1(k, 2) + vs2(k, 2)*tt_t1 + vs2(k, 3)*dt_t1 + vs2(k&
&       , 4)*ut_t1 + vs2(k, 5)*xt_t1
      bl1(k, 3) = vs1(k, 3) + vs2(k, 2)*tt_d1 + vs2(k, 3)*dt_d1 + vs2(k&
&       , 4)*ut_d1 + vs2(k, 5)*xt_d1
      bl1(k, 4) = vs1(k, 4) + vs2(k, 2)*tt_u1 + vs2(k, 3)*dt_u1 + vs2(k&
&       , 4)*ut_u1 + vs2(k, 5)*xt_u1
      bl1(k, 5) = vs1(k, 5) + vs2(k, 2)*tt_x1 + vs2(k, 3)*dt_x1 + vs2(k&
&       , 4)*ut_x1 + vs2(k, 5)*xt_x1
!
      bl2(k, 1) = 0.
      bl2(k, 2) = vs2(k, 2)*tt_t2 + vs2(k, 3)*dt_t2 + vs2(k, 4)*ut_t2 + &
&       vs2(k, 5)*xt_t2
      bl2(k, 3) = vs2(k, 2)*tt_d2 + vs2(k, 3)*dt_d2 + vs2(k, 4)*ut_d2 + &
&       vs2(k, 5)*xt_d2
      bl2(k, 4) = vs2(k, 2)*tt_u2 + vs2(k, 3)*dt_u2 + vs2(k, 4)*ut_u2 + &
&       vs2(k, 5)*xt_u2
      bl2(k, 5) = vs2(k, 2)*tt_x2 + vs2(k, 3)*dt_x2 + vs2(k, 4)*ut_x2 + &
&       vs2(k, 5)*xt_x2
    END DO
!
!
!
!**** SECOND, set up turbulent part between XT and X2  ****
!
!---- calculate equilibrium shear coefficient CQT at transition point
    CALL BLVAR(2)
!
!---- set initial shear coefficient value ST at transition point
!-    ( note that CQ2, CQ2_T2, etc. are really "CQT", "CQT_TT", etc.)
!
    ctr = ctrcon*EXP(-(ctrcex/(hk2-1.0)))
    ctr_hk2 = ctr*ctrcex/(hk2-1.0)**2
!
!      CTR     = 1.1*EXP(-10.0/HK2**2)
!      CTR_HK2 = CTR * 10.0 * 2.0/HK2**3
!
!CC      CTR = 1.2
!CC      CTR = 0.7
!CC      CTR_HK2 = 0.0
!
    st = ctr*cq2
    st_tt = ctr*cq2_t2 + cq2*ctr_hk2*hk2_t2
    st_dt = ctr*cq2_d2 + cq2*ctr_hk2*hk2_d2
    st_ut = ctr*cq2_u2 + cq2*ctr_hk2*hk2_u2
    st_ms = ctr*cq2_ms + cq2*ctr_hk2*hk2_ms
    st_re = ctr*cq2_re
!
!---- calculate ST sensitivities wrt the actual "1" and "2" variables
    st_a1 = st_tt*tt_a1 + st_dt*dt_a1 + st_ut*ut_a1
    st_x1 = st_tt*tt_x1 + st_dt*dt_x1 + st_ut*ut_x1
    st_x2 = st_tt*tt_x2 + st_dt*dt_x2 + st_ut*ut_x2
    st_t1 = st_tt*tt_t1 + st_dt*dt_t1 + st_ut*ut_t1
    st_t2 = st_tt*tt_t2 + st_dt*dt_t2 + st_ut*ut_t2
    st_d1 = st_tt*tt_d1 + st_dt*dt_d1 + st_ut*ut_d1
    st_d2 = st_tt*tt_d2 + st_dt*dt_d2 + st_ut*ut_d2
    st_u1 = st_tt*tt_u1 + st_dt*dt_u1 + st_ut*ut_u1
    st_u2 = st_tt*tt_u2 + st_dt*dt_u2 + st_ut*ut_u2
    st_ms = st_tt*tt_ms + st_dt*dt_ms + st_ut*ut_ms + st_ms
    st_re = st_tt*tt_re + st_dt*dt_re + st_ut*ut_re + st_re
    st_xf = st_tt*tt_xf + st_dt*dt_xf + st_ut*ut_xf
!
    ampl2 = 0.
    s2 = st
!
!---- recalculate turbulent secondary "T" variables using proper CTI
    CALL BLVAR(2)
!
!---- set "1" variables to "T" variables and reset "2" variables
!-    to their saved turbulent values
    CALL BLC_1FROM2()
    CALL BLC_RESTORE2()
!
!---- calculate XT-X2 midpoint CFM value
    CALL BLMID(2)
!
!---- set up Newton system for dCt, dTh, dDs, dUe, dXi  at  XT and X2
    CALL BLDIF(2)
!
!---- convert sensitivities wrt "T" variables into sensitivities
!-    wrt "1" and "2" variables as done before for the laminar part
    DO k=1,3
      btrez(k) = vsrez(k)
      btm(k) = vsm(k) + vs1(k, 1)*st_ms + vs1(k, 2)*tt_ms + vs1(k, 3)*&
&       dt_ms + vs1(k, 4)*ut_ms + vs1(k, 5)*xt_ms
      btr(k) = vsr(k) + vs1(k, 1)*st_re + vs1(k, 2)*tt_re + vs1(k, 3)*&
&       dt_re + vs1(k, 4)*ut_re + vs1(k, 5)*xt_re
      btx(k) = vsx(k) + vs1(k, 1)*st_xf + vs1(k, 2)*tt_xf + vs1(k, 3)*&
&       dt_xf + vs1(k, 4)*ut_xf + vs1(k, 5)*xt_xf
!
      bt1(k, 1) = vs1(k, 1)*st_a1 + vs1(k, 2)*tt_a1 + vs1(k, 3)*dt_a1 + &
&       vs1(k, 4)*ut_a1 + vs1(k, 5)*xt_a1
      bt1(k, 2) = vs1(k, 1)*st_t1 + vs1(k, 2)*tt_t1 + vs1(k, 3)*dt_t1 + &
&       vs1(k, 4)*ut_t1 + vs1(k, 5)*xt_t1
      bt1(k, 3) = vs1(k, 1)*st_d1 + vs1(k, 2)*tt_d1 + vs1(k, 3)*dt_d1 + &
&       vs1(k, 4)*ut_d1 + vs1(k, 5)*xt_d1
      bt1(k, 4) = vs1(k, 1)*st_u1 + vs1(k, 2)*tt_u1 + vs1(k, 3)*dt_u1 + &
&       vs1(k, 4)*ut_u1 + vs1(k, 5)*xt_u1
      bt1(k, 5) = vs1(k, 1)*st_x1 + vs1(k, 2)*tt_x1 + vs1(k, 3)*dt_x1 + &
&       vs1(k, 4)*ut_x1 + vs1(k, 5)*xt_x1
!
      bt2(k, 1) = vs2(k, 1)
      bt2(k, 2) = vs2(k, 2) + vs1(k, 1)*st_t2 + vs1(k, 2)*tt_t2 + vs1(k&
&       , 3)*dt_t2 + vs1(k, 4)*ut_t2 + vs1(k, 5)*xt_t2
      bt2(k, 3) = vs2(k, 3) + vs1(k, 1)*st_d2 + vs1(k, 2)*tt_d2 + vs1(k&
&       , 3)*dt_d2 + vs1(k, 4)*ut_d2 + vs1(k, 5)*xt_d2
      bt2(k, 4) = vs2(k, 4) + vs1(k, 1)*st_u2 + vs1(k, 2)*tt_u2 + vs1(k&
&       , 3)*dt_u2 + vs1(k, 4)*ut_u2 + vs1(k, 5)*xt_u2
      bt2(k, 5) = vs2(k, 5) + vs1(k, 1)*st_x2 + vs1(k, 2)*tt_x2 + vs1(k&
&       , 3)*dt_x2 + vs1(k, 4)*ut_x2 + vs1(k, 5)*xt_x2
    END DO
!
!
!---- Add up laminar and turbulent parts to get final system
!-    in terms of honest-to-God "1" and "2" variables.
    vsrez(1) = btrez(1)
    vsrez(2) = blrez(2) + btrez(2)
    vsrez(3) = blrez(3) + btrez(3)
    vsm(1) = btm(1)
    vsm(2) = blm(2) + btm(2)
    vsm(3) = blm(3) + btm(3)
    vsr(1) = btr(1)
    vsr(2) = blr(2) + btr(2)
    vsr(3) = blr(3) + btr(3)
    vsx(1) = btx(1)
    vsx(2) = blx(2) + btx(2)
    vsx(3) = blx(3) + btx(3)
    DO l=1,5
      vs1(1, l) = bt1(1, l)
      vs2(1, l) = bt2(1, l)
      vs1(2, l) = bl1(2, l) + bt1(2, l)
      vs2(2, l) = bl2(2, l) + bt2(2, l)
      vs1(3, l) = bl1(3, l) + bt1(3, l)
      vs2(3, l) = bl2(3, l) + bt2(3, l)
    END DO
!
!---- To be sanitary, restore "1" quantities which got clobbered
!-    in all of the numerical gymnastics above.  The "2" variables
!-    were already restored for the XT-X2 differencing part.
    CALL BLC_RESTORE1()
  END SUBROUTINE TRDIF

