&   cfx_t2, cfx_ta, cfx_upw, cfx_x1, cfx_x2, cfx_xa, cqa, da, ddlog, dea&
&   , dix, dix_upw, dxi, ehh, gcc, ha, hca, hdcon, hd_hk1, hd_hk2, hka, &
&   hkc, hkc_hka, hkc_rta, hl, hlog, hlsq, hl_hk1, hl_hk2, hr, hr_hka, &
&   hr_rta, hsa, hupwt, hwa, ma, rezc, rezh, rezt, rta, sa, scc, scc_us1&
&   , scc_us2, scc_usa, slog, ta, tlog, ulog, upw, upw_d1, upw_d2, &
&   upw_hd, upw_hk1, upw_hk2, upw_hl, upw_ms, upw_t1, upw_t2, upw_u1
    REAL :: upw_u2, uq
    REAL :: argd, axd, ax_a1d, ax_a2d, ax_hk1d, ax_hk2d, ax_rt1d, &
&   ax_rt2d, ax_t1d, ax_t2d, btmpd, cfad, cfxd, cfx_cf1d, cfx_cf2d, &
&   cfx_cfmd, cfx_t1d, cfx_t2d, cfx_tad, cfx_upwd, cfx_x1d, cfx_x2d, &
&   cfx_xad, cqad, dad, dead, dixd, dix_upwd, dxid, ehhd, had, hcad, &
&   hdcond, hd_hk2d, hkad, hkcd, hld, hlogd, hlsqd, hl_hk1d, hl_hk2d, &
&   hrd, hr_hkad, hsad, hwad, mad, rezcd, rezhd, reztd, rtad, sad, sccd&
&   , scc_usad, slogd, tad, tlogd, ulogd, upwd, upw_d1d, upw_d2d, &
&   upw_hdd, upw_hk1d, upw_hk2d, upw_hld, upw_msd, upw_t1d, upw_t2d, &
&   upw_u1d, upw_u2d, uqd
    INTEGER :: k, l
    REAL :: uq_cfa, uq_d1, uq_d2, uq_da, uq_hka, uq_ms, uq_re, uq_rta, &
&   uq_t1, uq_t2, uq_u1, uq_u2, uq_upw, usa, xa, xlog, xot1, xot2, z_ax&
&   , z_cf1, z_cf2, z_cfa, z_cfm, z_cfx, z_cq1, z_cq2, z_cqa, z_d1, z_d2&
&   , z_da, z_de1, z_de2, z_dea, z_di1, z_di2, z_dix, z_dxi, z_ha, z_hca&
&   , z_hk1, z_hk2, z_hka, z_hl, z_hs1, z_hs2, z_hwa, z_ma, z_s1, z_s2, &
&   z_sa, z_sl, z_t1, z_t2, z_tl, z_u1, z_u2, z_ul, z_upw, z_us1, z_us2&
&   , z_usa, z_x1, z_x2, z_xl
    REAL :: uq_cfad, uq_dad, uq_hkad, usad, xad, xlogd, xot1d, xot2d, &
&   z_axd, z_cf1d, z_cf2d, z_cfad, z_cfmd, z_cfxd, z_cq1d, z_cq2d, &
&   z_cqad, z_d1d, z_d2d, z_dad, z_de1d, z_de2d, z_dead, z_di1d, z_di2d&
&   , z_dixd, z_dxid, z_had, z_hcad, z_hk1d, z_hk2d, z_hkad, z_hs1d, &
&   z_hs2d, z_hwad, z_mad, z_s1d, z_s2d, z_sad, z_sld, z_t1d, z_t2d, &
&   z_u1d, z_u2d, z_uld, z_upwd, z_us1d, z_us2d, z_usad, z_x1d, z_x2d, &
&   z_xld
    INTRINSIC LOG
    INTRINSIC ABS
    INTRINSIC MIN
    INTRINSIC EXP
    REAL :: temp
    REAL :: temp0
    REAL :: temp1
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
    IF (ityp .EQ. 0) THEN
!----- similarity logarithmic differences  (prescribed)
      xlog = 1.0
      ulog = bule
      tlog = 0.5*(1.0-bule)
      hlog = 0.
      ddlog = 0.
      xlogd = 0.0_8
      ulogd = 0.0_8
      tlogd = 0.0_8
      hlogd = 0.0_8
    ELSE
!----- usual logarithmic differences
      temp = x2/x1
      xlogd = (x2d-temp*x1d)/(temp*x1)
      xlog = LOG(temp)
      temp = u2/u1
      ulogd = (u2d-temp*u1d)/(temp*u1)
      ulog = LOG(temp)
      temp = t2/t1
      tlogd = (t2d-temp*t1d)/(temp*t1)
      tlog = LOG(temp)
      temp = hs2/hs1
      hlogd = (hs2d-temp*hs1d)/(temp*hs1)
      hlog = LOG(temp)
!       XLOG = 2.0*(X2-X1)/(X2+X1)
!       ULOG = 2.0*(U2-U1)/(U2+U1)
!       TLOG = 2.0*(T2-T1)/(T2+T1)
!       HLOG = 2.0*(HS2-HS1)/(HS2+HS1)
      ddlog = 1.0
    END IF
!
    DO k=1,4
      vsrezd(k) = 0.0_8
      vsrez(k) = 0.
      vsmd(k) = 0.0_8
      vsm(k) = 0.
      vsrd(k) = 0.0_8
      vsr(k) = 0.
      vsxd(k) = 0.0_8
      vsx(k) = 0.
      DO l=1,5
        vs1d(k, l) = 0.0_8
        vs1(k, l) = 0.
        vs2d(k, l) = 0.0_8
        vs2(k, l) = 0.
      END DO
    END DO
!
!---- set triggering constant for local upwinding
    hupwt = 1.0
!
!cc      HDCON = 5.0*HUPWT
!cc      HD_HK1 = 0.0
!cc      HD_HK2 = 0.0
!
    temp = 5.0*hupwt/(hk2*hk2)
    hdcond = -(temp*2*hk2d/hk2)
    hdcon = temp
    hd_hk1 = 0.0
    hd_hk2d = -(2.0*(hdcond-hdcon*hk2d/hk2)/hk2)
    hd_hk2 = -(hdcon*2.0/hk2)
!
!---- use less upwinding in the wake
    IF (ityp .EQ. 3) THEN
      temp = hupwt/(hk2*hk2)
      hdcond = -(temp*2*hk2d/hk2)
      hdcon = temp
      hd_hk1 = 0.0
      hd_hk2d = -(2.0*(hdcond-hdcon*hk2d/hk2)/hk2)
      hd_hk2 = -(hdcon*2.0/hk2)
    END IF
    IF ((hk2-1.0)/(hk1-1.0) .GE. 0.) THEN
      temp = (hk2-1.0)/(hk1-1.0)
      argd = (hk2d-temp*hk1d)/(hk1-1.0)
      arg = temp
    ELSE
      temp = (hk2-1.0)/(hk1-1.0)
      argd = -((hk2d-temp*hk1d)/(hk1-1.0))
      arg = -temp
    END IF
    hld = argd/arg
    hl = LOG(arg)
    hl_hk1d = hk1d/(hk1-1.0)**2
    hl_hk1 = -(1.0/(hk1-1.0))
    hl_hk2d = -(hk2d/(hk2-1.0)**2)
    hl_hk2 = 1.0/(hk2-1.0)
    IF (hl**2 .GT. 15.0) THEN
      hlsq = 15.0
      hlsqd = 0.0_8
    ELSE
      hlsqd = 2*hl*hld
      hlsq = hl**2
    END IF
    ehhd = -(EXP(-(hlsq*hdcon))*(hdcon*hlsqd+hlsq*hdcond))
    ehh = EXP(-(hlsq*hdcon))
    upwd = -(0.5*ehhd)
    upw = 1.0 - 0.5*ehh
    upw_hld = hdcon*(hl*ehhd+ehh*hld) + ehh*hl*hdcond
    upw_hl = ehh*hl*hdcon
    upw_hdd = 0.5*(hlsq*ehhd+ehh*hlsqd)
    upw_hd = 0.5*ehh*hlsq
!
    upw_hk1d = hl_hk1*upw_hld + upw_hl*hl_hk1d + hd_hk1*upw_hdd
    upw_hk1 = upw_hl*hl_hk1 + upw_hd*hd_hk1
    upw_hk2d = hl_hk2*upw_hld + upw_hl*hl_hk2d + hd_hk2*upw_hdd + upw_hd&
&     *hd_hk2d
    upw_hk2 = upw_hl*hl_hk2 + upw_hd*hd_hk2
!
    upw_u1d = hk1_u1*upw_hk1d + upw_hk1*hk1_u1d
    upw_u1 = upw_hk1*hk1_u1
    upw_t1d = hk1_t1*upw_hk1d + upw_hk1*hk1_t1d
    upw_t1 = upw_hk1*hk1_t1
    upw_d1d = hk1_d1*upw_hk1d + upw_hk1*hk1_d1d
    upw_d1 = upw_hk1*hk1_d1
    upw_u2d = hk2_u2*upw_hk2d + upw_hk2*hk2_u2d
    upw_u2 = upw_hk2*hk2_u2
    upw_t2d = hk2_t2*upw_hk2d + upw_hk2*hk2_t2d
    upw_t2 = upw_hk2*hk2_t2
    upw_d2d = hk2_d2*upw_hk2d + upw_hk2*hk2_d2d
    upw_d2 = upw_hk2*hk2_d2
    upw_msd = hk1_ms*upw_hk1d + upw_hk1*hk1_msd + hk2_ms*upw_hk2d + &
&     upw_hk2*hk2_msd
    upw_ms = upw_hk1*hk1_ms + upw_hk2*hk2_ms
!
!
    IF (ityp .EQ. 0) THEN
!
!***** LE point -->  set zero amplification factor
      vs2d(1, 1) = 0.0_8
      vs2(1, 1) = 1.0
      vsrd(1) = 0.0_8
      vsr(1) = 0.
      vsrezd(1) = -ampl2d
      vsrez(1) = -ampl2
!
    ELSE IF (ityp .EQ. 1) THEN
!
!***** laminar part -->  set amplification equation
!
!----- set average amplification AX over interval X1..X2
      CALL AXSET_D(hk1, hk1d, t1, t1d, rt1, rt1d, ampl1, ampl1d, hk2, &
&            hk2d, t2, t2d, rt2, rt2d, ampl2, ampl2d, amcrit, amcritd, &
&            idampv, ax, axd, ax_hk1, ax_hk1d, ax_t1, ax_t1d, ax_rt1, &
&            ax_rt1d, ax_a1, ax_a1d, ax_hk2, ax_hk2d, ax_t2, ax_t2d, &
&            ax_rt2, ax_rt2d, ax_a2, ax_a2d)
!
      rezcd = ampl2d - ampl1d - (x2-x1)*axd - ax*(x2d-x1d)
      rezc = ampl2 - ampl1 - ax*(x2-x1)
      z_axd = x1d - x2d
      z_ax = -(x2-x1)
!
      vs1d(1, 1) = ax_a1*z_axd + z_ax*ax_a1d
      vs1(1, 1) = z_ax*ax_a1 - 1.0
      temp = ax_hk1*hk1_t1 + ax_t1 + ax_rt1*rt1_t1
      vs1d(1, 2) = temp*z_axd + z_ax*(hk1_t1*ax_hk1d+ax_hk1*hk1_t1d+&
&       ax_t1d+rt1_t1*ax_rt1d+ax_rt1*rt1_t1d)
      vs1(1, 2) = z_ax*temp
      vs1d(1, 3) = hk1_d1*(ax_hk1*z_axd+z_ax*ax_hk1d) + z_ax*ax_hk1*&
&       hk1_d1d
      vs1(1, 3) = z_ax*(ax_hk1*hk1_d1)
      temp = ax_hk1*hk1_u1 + ax_rt1*rt1_u1
      vs1d(1, 4) = temp*z_axd + z_ax*(hk1_u1*ax_hk1d+ax_hk1*hk1_u1d+&
&       rt1_u1*ax_rt1d+ax_rt1*rt1_u1d)
      vs1(1, 4) = z_ax*temp
      vs1d(1, 5) = axd
      vs1(1, 5) = ax
      vs2d(1, 1) = ax_a2*z_axd + z_ax*ax_a2d
      vs2(1, 1) = z_ax*ax_a2 + 1.0
      temp = ax_hk2*hk2_t2 + ax_t2 + ax_rt2*rt2_t2
      vs2d(1, 2) = temp*z_axd + z_ax*(hk2_t2*ax_hk2d+ax_hk2*hk2_t2d+&
&       ax_t2d+rt2_t2*ax_rt2d+ax_rt2*rt2_t2d)
      vs2(1, 2) = z_ax*temp
      vs2d(1, 3) = hk2_d2*(ax_hk2*z_axd+z_ax*ax_hk2d) + z_ax*ax_hk2*&
&       hk2_d2d
      vs2(1, 3) = z_ax*(ax_hk2*hk2_d2)
      temp = ax_hk2*hk2_u2 + ax_rt2*rt2_u2
      vs2d(1, 4) = temp*z_axd + z_ax*(hk2_u2*ax_hk2d+ax_hk2*hk2_u2d+&
&       rt2_u2*ax_rt2d+ax_rt2*rt2_u2d)
      vs2(1, 4) = z_ax*temp
      vs2d(1, 5) = -axd
      vs2(1, 5) = -ax
      temp = ax_hk1*hk1_ms + ax_rt1*rt1_ms + ax_hk2*hk2_ms + ax_rt2*&
&       rt2_ms
      vsmd(1) = temp*z_axd + z_ax*(hk1_ms*ax_hk1d+ax_hk1*hk1_msd+rt1_ms*&
&       ax_rt1d+ax_rt1*rt1_msd+hk2_ms*ax_hk2d+ax_hk2*hk2_msd+rt2_ms*&
&       ax_rt2d+ax_rt2*rt2_msd)
      vsm(1) = z_ax*temp
      temp = ax_rt1*rt1_re + ax_rt2*rt2_re
      vsrd(1) = temp*z_axd + z_ax*(rt1_re*ax_rt1d+ax_rt1*rt1_red+rt2_re*&
&       ax_rt2d+ax_rt2*rt2_red)
      vsr(1) = z_ax*temp
      vsxd(1) = 0.0_8
      vsx(1) = 0.
      vsrezd(1) = -rezcd
      vsrez(1) = -rezc
!
    ELSE
!
!***** turbulent part -->  set shear lag equation
!
      sad = (1.0-upw)*s1d - (s1-s2)*upwd + upw*s2d
      sa = (1.0-upw)*s1 + upw*s2
      cqad = (1.0-upw)*cq1d - (cq1-cq2)*upwd + upw*cq2d
      cqa = (1.0-upw)*cq1 + upw*cq2
      cfad = (1.0-upw)*cf1d - (cf1-cf2)*upwd + upw*cf2d
      cfa = (1.0-upw)*cf1 + upw*cf2
      hkad = (1.0-upw)*hk1d - (hk1-hk2)*upwd + upw*hk2d
      hka = (1.0-upw)*hk1 + upw*hk2
!
      usad = 0.5*(us1d+us2d)
      usa = 0.5*(us1+us2)
      rtad = 0.5*(rt1d+rt2d)
      rta = 0.5*(rt1+rt2)
      dead = 0.5*(de1d+de2d)
      dea = 0.5*(de1+de2)
      dad = 0.5*(d1d+d2d)
      da = 0.5*(d1+d2)
!
!
      IF (ityp .EQ. 3) THEN
!------ increased dissipation length in wake (decrease its reciprocal)
        ald = dlcon
      ELSE
        ald = 1.0
      END IF
!
!----- set and linearize  equilibrium 1/Ue dUe/dx   ...  NEW  12 Oct 94
      IF (ityp .EQ. 2) THEN
        gcc = gccon
        hkcd = hkad + gcc*rtad/rta**2
        hkc = hka - 1.0 - gcc/rta
        hkc_hka = 1.0
        hkc_rta = gcc/rta**2
        IF (hkc .LT. 0.01) THEN
          hkc = 0.01
          hkc_hka = 0.0
          hkc_rta = 0.0
          hkcd = 0.0_8
        END IF
      ELSE
        gcc = 0.0
        hkcd = hkad
        hkc = hka - 1.0
        hkc_hka = 1.0
        hkc_rta = 0.0
      END IF
!
      temp = gacon*ald*hka
      hrd = (hkcd-hkc*gacon*ald*hkad/temp)/temp
      hr = hkc/temp
      temp = hkc_hka/(gacon*ald*hka)
      hr_hkad = -(temp*hkad/hka) - (hrd-hr*hkad/hka)/hka
      hr_hka = temp - hr/hka
      hr_rta = hkc_rta/(gacon*ald*hka)
!
      temp = (0.5*cfa-hr*hr)/(gbcon*da)
      uqd = (0.5*cfad-2*hr*hrd-temp*gbcon*dad)/(gbcon*da)
      uq = temp
      temp = hr*hr_hka/(gbcon*da)
      uq_hkad = -(2.0*(hr_hka*hrd+hr*hr_hkad-temp*gbcon*dad)/(gbcon*da))
      uq_hka = -(2.0*temp)
      uq_rta = -(2.0*hr*hr_rta/(gbcon*da))
      temp = 0.5/(gbcon*da)
      uq_cfad = -(temp*dad/da)
      uq_cfa = temp
      uq_dad = -((uqd-uq*dad/da)/da)
      uq_da = -(uq/da)
      uq_upw = uq_cfa*(cf2-cf1) + uq_hka*(hk2-hk1)
!
      uq_t1 = (1.0-upw)*(uq_cfa*cf1_t1+uq_hka*hk1_t1) + uq_upw*upw_t1
      uq_d1 = (1.0-upw)*(uq_cfa*cf1_d1+uq_hka*hk1_d1) + uq_upw*upw_d1
      uq_u1 = (1.0-upw)*(uq_cfa*cf1_u1+uq_hka*hk1_u1) + uq_upw*upw_u1
      uq_t2 = upw*(uq_cfa*cf2_t2+uq_hka*hk2_t2) + uq_upw*upw_t2
      uq_d2 = upw*(uq_cfa*cf2_d2+uq_hka*hk2_d2) + uq_upw*upw_d2
      uq_u2 = upw*(uq_cfa*cf2_u2+uq_hka*hk2_u2) + uq_upw*upw_u2
      uq_ms = (1.0-upw)*(uq_cfa*cf1_ms+uq_hka*hk1_ms) + uq_upw*upw_ms + &
&       upw*(uq_cfa*cf2_ms+uq_hka*hk2_ms)
      uq_re = (1.0-upw)*uq_cfa*cf1_re + upw*uq_cfa*cf2_re
!
      uq_t1 = uq_t1 + 0.5*uq_rta*rt1_t1
      uq_d1 = uq_d1 + 0.5*uq_da
      uq_u1 = uq_u1 + 0.5*uq_rta*rt1_u1
      uq_t2 = uq_t2 + 0.5*uq_rta*rt2_t2
      uq_d2 = uq_d2 + 0.5*uq_da
      uq_u2 = uq_u2 + 0.5*uq_rta*rt2_u2
      uq_ms = uq_ms + 0.5*uq_rta*rt1_ms + 0.5*uq_rta*rt2_ms
      uq_re = uq_re + 0.5*uq_rta*rt1_re + 0.5*uq_rta*rt2_re
!
      temp = 1.333*sccon/(usa+1.0)
      sccd = -(temp*usad/(usa+1.0))
      scc = temp
      temp = scc/(usa+1.0)
      scc_usad = -((sccd-temp*usad)/(usa+1.0))
      scc_usa = -temp
!
      scc_us1 = scc_usa*0.5
      scc_us2 = scc_usa*0.5
!
!
      temp = s2/s1
      slogd = (s2d-temp*s1d)/(temp*s1)
      slog = LOG(temp)
      dxid = x2d - x1d
      dxi = x2 - x1
!
      rezcd = scc*dxi*(cqad-ald*sad) + (cqa-ald*sa)*(dxi*sccd+scc*dxid) &
&       - 2.0*(slog*dead+dea*slogd) + duxcon*2.0*((uq*dxi-ulog)*dead+dea&
&       *(dxi*uqd+uq*dxid-ulogd))
      rezc = scc*(cqa-sa*ald)*dxi - dea*2.0*slog + dea*2.0*(uq*dxi-ulog)&
&       *duxcon
!
!        if(  ! (rt2.gt.1.0e3 .and. rt1.le.1.0e3) .or.
!     &     (rt2.gt.1.0e4 .and. rt1.le.1.0e4) .or.
!     &     (rt2.gt.1.0e5 .and. rt1.le.1.0e5)        ) then
!           gga = (HKA-1.0-GCC/RTA)/HKA / sqrt(0.5*CFA)
!           write(*,4455) rta, hka, gga, cfa, cqa, sa, uq, ulog/dxi
! 4455      format(1x,f7.0, 2f9.4,f10.6,2f8.5,2f10.5)
!        endif
      z_cfad = duxcon*2.0*(dxi*(uq_cfa*dead+dea*uq_cfad)+dea*uq_cfa*dxid&
&       )
      z_cfa = dea*2.0*uq_cfa*dxi*duxcon
      z_hkad = duxcon*2.0*(dxi*(uq_hka*dead+dea*uq_hkad)+dea*uq_hka*dxid&
&       )
      z_hka = dea*2.0*uq_hka*dxi*duxcon
      z_dad = duxcon*2.0*(dxi*(uq_da*dead+dea*uq_dad)+dea*uq_da*dxid)
      z_da = dea*2.0*uq_da*dxi*duxcon
      z_sld = -(2.0*dead)
      z_sl = -(dea*2.0)
      z_uld = -(duxcon*2.0*dead)
      z_ul = -(dea*2.0*duxcon)
      z_dxid = (cqa-ald*sa)*sccd + scc*(cqad-ald*sad) + duxcon*2.0*(uq*&
&       dead+dea*uqd)
      z_dxi = scc*(cqa-sa*ald) + dea*2.0*uq*duxcon
      z_usad = scc_usa*dxi*(cqad-ald*sad) + (cqa-ald*sa)*(dxi*scc_usad+&
&       scc_usa*dxid)
      z_usa = scc_usa*(cqa-sa*ald)*dxi
      z_cqad = dxi*sccd + scc*dxid
      z_cqa = scc*dxi
      z_sad = -(ald*(dxi*sccd+scc*dxid))
      z_sa = -(scc*dxi*ald)
      z_dead = 2.0*(duxcon*(dxi*uqd+uq*dxid-ulogd)-slogd)
      z_dea = 2.0*((uq*dxi-ulog)*duxcon-slog)
!
      z_upwd = (cq2-cq1)*z_cqad + z_cqa*(cq2d-cq1d) + (s2-s1)*z_sad + &
&       z_sa*(s2d-s1d) + (cf2-cf1)*z_cfad + z_cfa*(cf2d-cf1d) + (hk2-hk1&
&       )*z_hkad + z_hka*(hk2d-hk1d)
      z_upw = z_cqa*(cq2-cq1) + z_sa*(s2-s1) + z_cfa*(cf2-cf1) + z_hka*(&
&       hk2-hk1)
      z_de1d = 0.5*z_dead
      z_de1 = 0.5*z_dea
      z_de2d = 0.5*z_dead
      z_de2 = 0.5*z_dea
      z_us1d = 0.5*z_usad
      z_us1 = 0.5*z_usa
      z_us2d = 0.5*z_usad
      z_us2 = 0.5*z_usa
      z_d1d = 0.5*z_dad
      z_d1 = 0.5*z_da
      z_d2d = 0.5*z_dad
      z_d2 = 0.5*z_da
      z_u1d = -((z_uld-z_ul*u1d/u1)/u1)
      z_u1 = -(z_ul/u1)
      z_u2d = (z_uld-z_ul*u2d/u2)/u2
      z_u2 = z_ul/u2
      z_x1d = -z_dxid
      z_x1 = -z_dxi
      z_x2d = z_dxid
      z_x2 = z_dxi
      z_s1d = (1.0-upw)*z_sad - z_sa*upwd - (z_sld-z_sl*s1d/s1)/s1
      z_s1 = (1.0-upw)*z_sa - z_sl/s1
      z_s2d = z_sa*upwd + upw*z_sad + (z_sld-z_sl*s2d/s2)/s2
      z_s2 = upw*z_sa + z_sl/s2
      z_cq1d = (1.0-upw)*z_cqad - z_cqa*upwd
      z_cq1 = (1.0-upw)*z_cqa
      z_cq2d = z_cqa*upwd + upw*z_cqad
      z_cq2 = upw*z_cqa
      z_cf1d = (1.0-upw)*z_cfad - z_cfa*upwd
      z_cf1 = (1.0-upw)*z_cfa
      z_cf2d = z_cfa*upwd + upw*z_cfad
      z_cf2 = upw*z_cfa
      z_hk1d = (1.0-upw)*z_hkad - z_hka*upwd
      z_hk1 = (1.0-upw)*z_hka
      z_hk2d = z_hka*upwd + upw*z_hkad
      z_hk2 = upw*z_hka
!
      vs1d(1, 1) = z_s1d
      vs1(1, 1) = z_s1
      vs1d(1, 2) = upw_t1*z_upwd + z_upw*upw_t1d + de1_t1*z_de1d + z_de1&
&       *de1_t1d + us1_t1*z_us1d + z_us1*us1_t1d
      vs1(1, 2) = z_upw*upw_t1 + z_de1*de1_t1 + z_us1*us1_t1
      vs1d(1, 3) = z_d1d + upw_d1*z_upwd + z_upw*upw_d1d + de1_d1*z_de1d&
&       + z_de1*de1_d1d + us1_d1*z_us1d + z_us1*us1_d1d
      vs1(1, 3) = z_d1 + z_upw*upw_d1 + z_de1*de1_d1 + z_us1*us1_d1
      vs1d(1, 4) = z_u1d + upw_u1*z_upwd + z_upw*upw_u1d + de1_u1*z_de1d&
&       + z_de1*de1_u1d + us1_u1*z_us1d + z_us1*us1_u1d
      vs1(1, 4) = z_u1 + z_upw*upw_u1 + z_de1*de1_u1 + z_us1*us1_u1
      vs1d(1, 5) = z_x1d
      vs1(1, 5) = z_x1
      vs2d(1, 1) = z_s2d
      vs2(1, 1) = z_s2
      vs2d(1, 2) = upw_t2*z_upwd + z_upw*upw_t2d + de2_t2*z_de2d + z_de2&
&       *de2_t2d + us2_t2*z_us2d + z_us2*us2_t2d
      vs2(1, 2) = z_upw*upw_t2 + z_de2*de2_t2 + z_us2*us2_t2
      vs2d(1, 3) = z_d2d + upw_d2*z_upwd + z_upw*upw_d2d + de2_d2*z_de2d&
&       + z_de2*de2_d2d + us2_d2*z_us2d + z_us2*us2_d2d
      vs2(1, 3) = z_d2 + z_upw*upw_d2 + z_de2*de2_d2 + z_us2*us2_d2
      vs2d(1, 4) = z_u2d + upw_u2*z_upwd + z_upw*upw_u2d + de2_u2*z_de2d&
&       + z_de2*de2_u2d + us2_u2*z_us2d + z_us2*us2_u2d
      vs2(1, 4) = z_u2 + z_upw*upw_u2 + z_de2*de2_u2 + z_us2*us2_u2
      vs2d(1, 5) = z_x2d
      vs2(1, 5) = z_x2
      vsmd(1) = upw_ms*z_upwd + z_upw*upw_msd + de1_ms*z_de1d + z_de1*&
&       de1_msd + us1_ms*z_us1d + z_us1*us1_msd + de2_ms*z_de2d + z_de2*&
&       de2_msd + us2_ms*z_us2d + z_us2*us2_msd
      vsm(1) = z_upw*upw_ms + z_de1*de1_ms + z_us1*us1_ms + z_de2*de2_ms&
&       + z_us2*us2_ms
!
      vs1d(1, 2) = vs1d(1, 2) + cq1_t1*z_cq1d + z_cq1*cq1_t1d + cf1_t1*&
&       z_cf1d + z_cf1*cf1_t1d + hk1_t1*z_hk1d + z_hk1*hk1_t1d
      vs1(1, 2) = vs1(1, 2) + z_cq1*cq1_t1 + z_cf1*cf1_t1 + z_hk1*hk1_t1
      vs1d(1, 3) = vs1d(1, 3) + cq1_d1*z_cq1d + z_cq1*cq1_d1d + cf1_d1*&
&       z_cf1d + z_cf1*cf1_d1d + hk1_d1*z_hk1d + z_hk1*hk1_d1d
      vs1(1, 3) = vs1(1, 3) + z_cq1*cq1_d1 + z_cf1*cf1_d1 + z_hk1*hk1_d1
      vs1d(1, 4) = vs1d(1, 4) + cq1_u1*z_cq1d + z_cq1*cq1_u1d + cf1_u1*&
&       z_cf1d + z_cf1*cf1_u1d + hk1_u1*z_hk1d + z_hk1*hk1_u1d
      vs1(1, 4) = vs1(1, 4) + z_cq1*cq1_u1 + z_cf1*cf1_u1 + z_hk1*hk1_u1
!
      vs2d(1, 2) = vs2d(1, 2) + cq2_t2*z_cq2d + z_cq2*cq2_t2d + cf2_t2*&
&       z_cf2d + z_cf2*cf2_t2d + hk2_t2*z_hk2d + z_hk2*hk2_t2d
      vs2(1, 2) = vs2(1, 2) + z_cq2*cq2_t2 + z_cf2*cf2_t2 + z_hk2*hk2_t2
      vs2d(1, 3) = vs2d(1, 3) + cq2_d2*z_cq2d + z_cq2*cq2_d2d + cf2_d2*&
&       z_cf2d + z_cf2*cf2_d2d + hk2_d2*z_hk2d + z_hk2*hk2_d2d
      vs2(1, 3) = vs2(1, 3) + z_cq2*cq2_d2 + z_cf2*cf2_d2 + z_hk2*hk2_d2
      vs2d(1, 4) = vs2d(1, 4) + cq2_u2*z_cq2d + z_cq2*cq2_u2d + cf2_u2*&
&       z_cf2d + z_cf2*cf2_u2d + hk2_u2*z_hk2d + z_hk2*hk2_u2d
      vs2(1, 4) = vs2(1, 4) + z_cq2*cq2_u2 + z_cf2*cf2_u2 + z_hk2*hk2_u2
!
      vsmd(1) = vsmd(1) + cq1_ms*z_cq1d + z_cq1*cq1_msd + cf1_ms*z_cf1d &
&       + z_cf1*cf1_msd + hk1_ms*z_hk1d + z_hk1*hk1_msd + cq2_ms*z_cq2d &
&       + z_cq2*cq2_msd + cf2_ms*z_cf2d + z_cf2*cf2_msd + hk2_ms*z_hk2d &
&       + z_hk2*hk2_msd
      vsm(1) = vsm(1) + z_cq1*cq1_ms + z_cf1*cf1_ms + z_hk1*hk1_ms + &
&       z_cq2*cq2_ms + z_cf2*cf2_ms + z_hk2*hk2_ms
      vsrd(1) = cq1_re*z_cq1d + z_cq1*cq1_red + cf1_re*z_cf1d + z_cf1*&
&       cf1_red + cq2_re*z_cq2d + z_cq2*cq2_red + cf2_re*z_cf2d + z_cf2*&
&       cf2_red
      vsr(1) = z_cq1*cq1_re + z_cf1*cf1_re + z_cq2*cq2_re + z_cf2*cf2_re
      vsxd(1) = 0.0_8
      vsx(1) = 0.
      vsrezd(1) = -rezcd
      vsrez(1) = -rezc
!
    END IF
!
!**** Set up momentum equation
    had = 0.5*(h1d+h2d)
    ha = 0.5*(h1+h2)
    mad = 0.5*(m1d+m2d)
    ma = 0.5*(m1+m2)
    xad = 0.5*(x1d+x2d)
    xa = 0.5*(x1+x2)
    tad = 0.5*(t1d+t2d)
    ta = 0.5*(t1+t2)
    hwad = 0.5*((dw1d-dw1*t1d/t1)/t1+(dw2d-dw2*t2d/t2)/t2)
    hwa = 0.5*(dw1/t1+dw2/t2)
!
!---- set Cf term, using central value CFM for better accuracy in drag
    temp = cfm*xa/ta
    temp0 = cf1*x1/t1
    temp1 = cf2*x2/t2
    cfxd = 0.50*(xa*cfmd+cfm*xad-temp*tad)/ta + 0.25*((x1*cf1d+cf1*x1d-&
&     temp0*t1d)/t1+(x2*cf2d+cf2*x2d-temp1*t2d)/t2)
    cfx = 0.50*temp + 0.25*(temp0+temp1)
    cfx_xad = 0.50*(cfmd-cfm*tad/ta)/ta
    cfx_xa = 0.50*cfm/ta
    temp1 = cfm*xa/(ta*ta)
    cfx_tad = -(.50*(xa*cfmd+cfm*xad-temp1*2*ta*tad)/ta**2)
    cfx_ta = -(.50*temp1)
!
    cfx_x1d = 0.25*(cf1d-cf1*t1d/t1)/t1 + 0.5*cfx_xad
    cfx_x1 = 0.25*cf1/t1 + cfx_xa*0.5
    cfx_x2d = 0.25*(cf2d-cf2*t2d/t2)/t2 + 0.5*cfx_xad
    cfx_x2 = 0.25*cf2/t2 + cfx_xa*0.5
    temp1 = cf1*x1/(t1*t1)
    cfx_t1d = 0.5*cfx_tad - .25*(x1*cf1d+cf1*x1d-temp1*2*t1*t1d)/t1**2
    cfx_t1 = 0.5*cfx_ta - .25*temp1
    temp1 = cf2*x2/(t2*t2)
    cfx_t2d = 0.5*cfx_tad - .25*(x2*cf2d+cf2*x2d-temp1*2*t2*t2d)/t2**2
    cfx_t2 = 0.5*cfx_ta - .25*temp1
    cfx_cf1d = 0.25*(x1d-x1*t1d/t1)/t1
    cfx_cf1 = 0.25*x1/t1
    cfx_cf2d = 0.25*(x2d-x2*t2d/t2)/t2
    cfx_cf2 = 0.25*x2/t2
    cfx_cfmd = 0.50*(xad-xa*tad/ta)/ta
    cfx_cfm = 0.50*xa/ta
!
    btmpd = had - mad + hwad
    btmp = ha + 2.0 - ma + hwa
!
    reztd = tlogd + ulog*btmpd + btmp*ulogd - 0.5*(cfx*xlogd+xlog*cfxd)
    rezt = tlog + btmp*ulog - xlog*0.5*cfx
    z_cfxd = -(0.5*xlogd)
    z_cfx = -(xlog*0.5)
    z_had = ulogd
    z_ha = ulog
    z_hwad = ulogd
    z_hwa = ulog
    z_mad = -ulogd
    z_ma = -ulog
    z_xld = -(ddlog*0.5*cfxd)
    z_xl = -(ddlog*0.5*cfx)
    z_uld = ddlog*btmpd
    z_ul = ddlog*btmp
    z_tl = ddlog
!
    z_cfmd = cfx_cfm*z_cfxd + z_cfx*cfx_cfmd
    z_cfm = z_cfx*cfx_cfm
    z_cf1d = cfx_cf1*z_cfxd + z_cfx*cfx_cf1d
    z_cf1 = z_cfx*cfx_cf1
    z_cf2d = cfx_cf2*z_cfxd + z_cfx*cfx_cf2d
    z_cf2 = z_cfx*cfx_cf2
!
    temp1 = z_hwa*dw1/(t1*t1)
    z_t1d = cfx_t1*z_cfxd + z_cfx*cfx_t1d + z_tl*t1d/t1**2 - 0.5*(dw1*&
&     z_hwad+z_hwa*dw1d-temp1*2*t1*t1d)/t1**2
    z_t1 = z_cfx*cfx_t1 - z_tl/t1 - 0.5*temp1
    temp1 = z_hwa*dw2/(t2*t2)
    z_t2d = cfx_t2*z_cfxd - z_tl*t2d/t2**2 + z_cfx*cfx_t2d - 0.5*(dw2*&
&     z_hwad+z_hwa*dw2d-temp1*2*t2*t2d)/t2**2
    z_t2 = z_tl/t2 + z_cfx*cfx_t2 - 0.5*temp1
    z_x1d = cfx_x1*z_cfxd + z_cfx*cfx_x1d - (z_xld-z_xl*x1d/x1)/x1
    z_x1 = -(z_xl/x1) + z_cfx*cfx_x1
    z_x2d = (z_xld-z_xl*x2d/x2)/x2 + cfx_x2*z_cfxd + z_cfx*cfx_x2d
    z_x2 = z_xl/x2 + z_cfx*cfx_x2
    z_u1d = -((z_uld-z_ul*u1d/u1)/u1)
    z_u1 = -(z_ul/u1)
    z_u2d = (z_uld-z_ul*u2d/u2)/u2
    z_u2 = z_ul/u2
!
    vs1d(2, 2) = 0.5*(h1_t1*z_had+z_ha*h1_t1d) + cfm_t1*z_cfmd + z_cfm*&
&     cfm_t1d + cf1_t1*z_cf1d + z_cf1*cf1_t1d + z_t1d
    vs1(2, 2) = 0.5*z_ha*h1_t1 + z_cfm*cfm_t1 + z_cf1*cf1_t1 + z_t1
    vs1d(2, 3) = 0.5*(h1_d1*z_had+z_ha*h1_d1d) + cfm_d1*z_cfmd + z_cfm*&
&     cfm_d1d + cf1_d1*z_cf1d + z_cf1*cf1_d1d
    vs1(2, 3) = 0.5*z_ha*h1_d1 + z_cfm*cfm_d1 + z_cf1*cf1_d1
    vs1d(2, 4) = 0.5*(m1_u1*z_mad+z_ma*m1_u1d) + cfm_u1*z_cfmd + z_cfm*&
&     cfm_u1d + cf1_u1*z_cf1d + z_cf1*cf1_u1d + z_u1d
    vs1(2, 4) = 0.5*z_ma*m1_u1 + z_cfm*cfm_u1 + z_cf1*cf1_u1 + z_u1
    vs1d(2, 5) = z_x1d
    vs1(2, 5) = z_x1
    vs2d(2, 2) = 0.5*(h2_t2*z_had+z_ha*h2_t2d) + cfm_t2*z_cfmd + z_cfm*&
&     cfm_t2d + cf2_t2*z_cf2d + z_cf2*cf2_t2d + z_t2d
    vs2(2, 2) = 0.5*z_ha*h2_t2 + z_cfm*cfm_t2 + z_cf2*cf2_t2 + z_t2
    vs2d(2, 3) = 0.5*(h2_d2*z_had+z_ha*h2_d2d) + cfm_d2*z_cfmd + z_cfm*&
&     cfm_d2d + cf2_d2*z_cf2d + z_cf2*cf2_d2d
    vs2(2, 3) = 0.5*z_ha*h2_d2 + z_cfm*cfm_d2 + z_cf2*cf2_d2
    vs2d(2, 4) = 0.5*(m2_u2*z_mad+z_ma*m2_u2d) + cfm_u2*z_cfmd + z_cfm*&
&     cfm_u2d + cf2_u2*z_cf2d + z_cf2*cf2_u2d + z_u2d
    vs2(2, 4) = 0.5*z_ma*m2_u2 + z_cfm*cfm_u2 + z_cf2*cf2_u2 + z_u2
    vs2d(2, 5) = z_x2d
    vs2(2, 5) = z_x2
!
    vsmd(2) = 0.5*(m1_ms*z_mad+z_ma*m1_msd) + cfm_ms*z_cfmd + z_cfm*&
&     cfm_msd + cf1_ms*z_cf1d + z_cf1*cf1_msd + 0.5*(m2_ms*z_mad+z_ma*&
&     m2_msd) + cf2_ms*z_cf2d + z_cf2*cf2_msd
    vsm(2) = 0.5*z_ma*m1_ms + z_cfm*cfm_ms + z_cf1*cf1_ms + 0.5*z_ma*&
&     m2_ms + z_cf2*cf2_ms
    vsrd(2) = cfm_re*z_cfmd + z_cfm*cfm_red + cf1_re*z_cf1d + z_cf1*&
&     cf1_red + cf2_re*z_cf2d + z_cf2*cf2_red
    vsr(2) = z_cfm*cfm_re + z_cf1*cf1_re + z_cf2*cf2_re
    vsxd(2) = 0.0_8
    vsx(2) = 0.
    vsrezd(2) = -reztd
    vsrez(2) = -rezt
!
!**** Set up shape parameter equation
!
    xot1d = (x1d-x1*t1d/t1)/t1
    xot1 = x1/t1
    xot2d = (x2d-x2*t2d/t2)/t2
    xot2 = x2/t2
!
    had = 0.5*(h1d+h2d)
    ha = 0.5*(h1+h2)
    hsad = 0.5*(hs1d+hs2d)
    hsa = 0.5*(hs1+hs2)
    hcad = 0.5*(hc1d+hc2d)
    hca = 0.5*(hc1+hc2)
    hwad = 0.5*((dw1d-dw1*t1d/t1)/t1+(dw2d-dw2*t2d/t2)/t2)
    hwa = 0.5*(dw1/t1+dw2/t2)
!
    dixd = (1.0-upw)*(xot1*di1d+di1*xot1d) - di1*xot1*upwd + xot2*(di2*&
&     upwd+upw*di2d) + upw*di2*xot2d
    dix = (1.0-upw)*di1*xot1 + upw*di2*xot2
    cfxd = (1.0-upw)*(xot1*cf1d+cf1*xot1d) - cf1*xot1*upwd + xot2*(cf2*&
&     upwd+upw*cf2d) + upw*cf2*xot2d
    cfx = (1.0-upw)*cf1*xot1 + upw*cf2*xot2
    dix_upwd = xot2*di2d + di2*xot2d - xot1*di1d - di1*xot1d
    dix_upw = di2*xot2 - di1*xot1
    cfx_upwd = xot2*cf2d + cf2*xot2d - xot1*cf1d - cf1*xot1d
    cfx_upw = cf2*xot2 - cf1*xot1
!
    btmpd = 2.0*(hcad-hca*hsad/hsa)/hsa - had - hwad
    btmp = 2.0*hca/hsa + 1.0 - ha - hwa
!
    rezhd = hlogd + ulog*btmpd + btmp*ulogd + (0.5*cfx-dix)*xlogd + xlog&
&     *(0.5*cfxd-dixd)
    rezh = hlog + btmp*ulog + xlog*(0.5*cfx-dix)
    z_cfxd = 0.5*xlogd
    z_cfx = xlog*0.5
    z_dixd = -xlogd
    z_dix = -xlog
    z_hcad = 2.0*(ulogd-ulog*hsad/hsa)/hsa
    z_hca = 2.0*ulog/hsa
    z_had = -ulogd
    z_ha = -ulog
    z_hwad = -ulogd
    z_hwa = -ulog
    z_xld = ddlog*(0.5*cfxd-dixd)
    z_xl = ddlog*(0.5*cfx-dix)
    z_uld = ddlog*btmpd
    z_ul = ddlog*btmp
    z_hl = ddlog
!
    z_upwd = cfx_upw*z_cfxd + z_cfx*cfx_upwd + dix_upw*z_dixd + z_dix*&
&     dix_upwd
    z_upw = z_cfx*cfx_upw + z_dix*dix_upw
!
    temp1 = hca*ulog/(hsa*hsa)
    z_hs1d = z_hl*hs1d/hs1**2 - (ulog*hcad+hca*ulogd-temp1*2*hsa*hsad)/&
&     hsa**2
    z_hs1 = -temp1 - z_hl/hs1
    temp1 = hca*ulog/(hsa*hsa)
    z_hs2d = -(z_hl*hs2d/hs2**2) - (ulog*hcad+hca*ulogd-temp1*2*hsa*hsad&
&     )/hsa**2
    z_hs2 = z_hl/hs2 - temp1
!
    z_cf1d = (1.0-upw)*(xot1*z_cfxd+z_cfx*xot1d) - z_cfx*xot1*upwd
    z_cf1 = (1.0-upw)*z_cfx*xot1
    z_cf2d = xot2*(z_cfx*upwd+upw*z_cfxd) + upw*z_cfx*xot2d
    z_cf2 = upw*z_cfx*xot2
    z_di1d = (1.0-upw)*(xot1*z_dixd+z_dix*xot1d) - z_dix*xot1*upwd
    z_di1 = (1.0-upw)*z_dix*xot1
    z_di2d = xot2*(z_dix*upwd+upw*z_dixd) + upw*z_dix*xot2d
    z_di2 = upw*z_dix*xot2
!
    temp1 = xot1/t1
    temp0 = z_cfx*cf1 + z_dix*di1
    z_t1d = -((1.0-upw)*temp1*(cf1*z_cfxd+z_cfx*cf1d+di1*z_dixd+z_dix*&
&     di1d)+temp0*((1.0-upw)*(xot1d-temp1*t1d)/t1-temp1*upwd))
    z_t1 = -(temp0*((1.0-upw)*temp1))
    temp1 = upw*xot2/t2
    temp0 = z_cfx*cf2 + z_dix*di2
    z_t2d = -(temp1*(cf2*z_cfxd+z_cfx*cf2d+di2*z_dixd+z_dix*di2d)+temp0*&
&     (xot2*upwd+upw*xot2d-temp1*t2d)/t2)
    z_t2 = -(temp0*temp1)
    temp1 = z_cfx*cf1 + z_dix*di1
    temp0 = (-upw+1.0)/t1
    z_x1d = temp1*(-upwd-temp0*t1d)/t1 + temp0*(cf1*z_cfxd+z_cfx*cf1d+&
&     di1*z_dixd+z_dix*di1d) - (z_xld-z_xl*x1d/x1)/x1
    z_x1 = temp0*temp1 - z_xl/x1
    temp1 = upw/t2
    temp0 = z_cfx*cf2 + z_dix*di2
    z_x2d = temp1*(cf2*z_cfxd+z_cfx*cf2d+di2*z_dixd+z_dix*di2d) + temp0*&
&     (upwd-temp1*t2d)/t2 + (z_xld-z_xl*x2d/x2)/x2
    z_x2 = temp0*temp1 + z_xl/x2
    z_u1d = -((z_uld-z_ul*u1d/u1)/u1)
    z_u1 = -(z_ul/u1)
    z_u2d = (z_uld-z_ul*u2d/u2)/u2
    z_u2 = z_ul/u2
!
    temp1 = z_hwa*dw1/(t1*t1)
    z_t1d = z_t1d - 0.5*(dw1*z_hwad+z_hwa*dw1d-temp1*2*t1*t1d)/t1**2
    z_t1 = z_t1 - 0.5*temp1
    temp1 = z_hwa*dw2/(t2*t2)
    z_t2d = z_t2d - 0.5*(dw2*z_hwad+z_hwa*dw2d-temp1*2*t2*t2d)/t2**2
    z_t2 = z_t2 - 0.5*temp1
!
    vs1d(3, 1) = di1_s1*z_di1d + z_di1*di1_s1d
    vs1(3, 1) = z_di1*di1_s1
    vs1d(3, 2) = hs1_t1*z_hs1d + z_hs1*hs1_t1d + cf1_t1*z_cf1d + z_cf1*&
&     cf1_t1d + di1_t1*z_di1d + z_di1*di1_t1d + z_t1d
    vs1(3, 2) = z_hs1*hs1_t1 + z_cf1*cf1_t1 + z_di1*di1_t1 + z_t1
    vs1d(3, 3) = hs1_d1*z_hs1d + z_hs1*hs1_d1d + cf1_d1*z_cf1d + z_cf1*&
&     cf1_d1d + di1_d1*z_di1d + z_di1*di1_d1d
    vs1(3, 3) = z_hs1*hs1_d1 + z_cf1*cf1_d1 + z_di1*di1_d1
    vs1d(3, 4) = hs1_u1*z_hs1d + z_hs1*hs1_u1d + cf1_u1*z_cf1d + z_cf1*&
&     cf1_u1d + di1_u1*z_di1d + z_di1*di1_u1d + z_u1d
    vs1(3, 4) = z_hs1*hs1_u1 + z_cf1*cf1_u1 + z_di1*di1_u1 + z_u1
    vs1d(3, 5) = z_x1d
    vs1(3, 5) = z_x1
    vs2d(3, 1) = di2_s2*z_di2d + z_di2*di2_s2d
    vs2(3, 1) = z_di2*di2_s2
    vs2d(3, 2) = hs2_t2*z_hs2d + z_hs2*hs2_t2d + cf2_t2*z_cf2d + z_cf2*&
&     cf2_t2d + di2_t2*z_di2d + z_di2*di2_t2d + z_t2d
    vs2(3, 2) = z_hs2*hs2_t2 + z_cf2*cf2_t2 + z_di2*di2_t2 + z_t2
    vs2d(3, 3) = hs2_d2*z_hs2d + z_hs2*hs2_d2d + cf2_d2*z_cf2d + z_cf2*&
&     cf2_d2d + di2_d2*z_di2d + z_di2*di2_d2d
    vs2(3, 3) = z_hs2*hs2_d2 + z_cf2*cf2_d2 + z_di2*di2_d2
    vs2d(3, 4) = hs2_u2*z_hs2d + z_hs2*hs2_u2d + cf2_u2*z_cf2d + z_cf2*&
&     cf2_u2d + di2_u2*z_di2d + z_di2*di2_u2d + z_u2d
    vs2(3, 4) = z_hs2*hs2_u2 + z_cf2*cf2_u2 + z_di2*di2_u2 + z_u2
    vs2d(3, 5) = z_x2d
    vs2(3, 5) = z_x2
    vsmd(3) = hs1_ms*z_hs1d + z_hs1*hs1_msd + cf1_ms*z_cf1d + z_cf1*&
&     cf1_msd + di1_ms*z_di1d + z_di1*di1_msd + hs2_ms*z_hs2d + z_hs2*&
&     hs2_msd + cf2_ms*z_cf2d + z_cf2*cf2_msd + di2_ms*z_di2d + z_di2*&
&     di2_msd
    vsm(3) = z_hs1*hs1_ms + z_cf1*cf1_ms + z_di1*di1_ms + z_hs2*hs2_ms +&
&     z_cf2*cf2_ms + z_di2*di2_ms
    vsrd(3) = hs1_re*z_hs1d + z_hs1*hs1_red + cf1_re*z_cf1d + z_cf1*&
&     cf1_red + di1_re*z_di1d + z_di1*di1_red + hs2_re*z_hs2d + z_hs2*&
&     hs2_red + cf2_re*z_cf2d + z_cf2*cf2_red + di2_re*z_di2d + z_di2*&
&     di2_red
    vsr(3) = z_hs1*hs1_re + z_cf1*cf1_re + z_di1*di1_re + z_hs2*hs2_re +&
&     z_cf2*cf2_re + z_di2*di2_re
!
    vs1d(3, 2) = vs1d(3, 2) + 0.5*(hc1_t1*z_hcad+z_hca*hc1_t1d+h1_t1*&
&     z_had+z_ha*h1_t1d) + upw_t1*z_upwd + z_upw*upw_t1d
    vs1(3, 2) = vs1(3, 2) + 0.5*(z_hca*hc1_t1+z_ha*h1_t1) + z_upw*upw_t1
    vs1d(3, 3) = vs1d(3, 3) + 0.5*(hc1_d1*z_hcad+z_hca*hc1_d1d+h1_d1*&
&     z_had+z_ha*h1_d1d) + upw_d1*z_upwd + z_upw*upw_d1d
    vs1(3, 3) = vs1(3, 3) + 0.5*(z_hca*hc1_d1+z_ha*h1_d1) + z_upw*upw_d1
    vs1d(3, 4) = vs1d(3, 4) + 0.5*(hc1_u1*z_hcad+z_hca*hc1_u1d) + upw_u1&
&     *z_upwd + z_upw*upw_u1d
    vs1(3, 4) = vs1(3, 4) + 0.5*(z_hca*hc1_u1) + z_upw*upw_u1
    vs2d(3, 2) = vs2d(3, 2) + 0.5*(hc2_t2*z_hcad+z_hca*hc2_t2d+h2_t2*&
&     z_had+z_ha*h2_t2d) + upw_t2*z_upwd + z_upw*upw_t2d
    vs2(3, 2) = vs2(3, 2) + 0.5*(z_hca*hc2_t2+z_ha*h2_t2) + z_upw*upw_t2
    vs2d(3, 3) = vs2d(3, 3) + 0.5*(hc2_d2*z_hcad+z_hca*hc2_d2d+h2_d2*&
&     z_had+z_ha*h2_d2d) + upw_d2*z_upwd + z_upw*upw_d2d
    vs2(3, 3) = vs2(3, 3) + 0.5*(z_hca*hc2_d2+z_ha*h2_d2) + z_upw*upw_d2
    vs2d(3, 4) = vs2d(3, 4) + 0.5*(hc2_u2*z_hcad+z_hca*hc2_u2d) + upw_u2&
&     *z_upwd + z_upw*upw_u2d
    vs2(3, 4) = vs2(3, 4) + 0.5*(z_hca*hc2_u2) + z_upw*upw_u2
!
    vsmd(3) = vsmd(3) + 0.5*(hc1_ms*z_hcad+z_hca*hc1_msd) + upw_ms*&
&     z_upwd + z_upw*upw_msd + 0.5*(hc2_ms*z_hcad+z_hca*hc2_msd)
    vsm(3) = vsm(3) + 0.5*(z_hca*hc1_ms) + z_upw*upw_ms + 0.5*(z_hca*&
&     hc2_ms)
!
    vsxd(3) = 0.0_8
    vsx(3) = 0.
    vsrezd(3) = -rezhd
    vsrez(3) = -rezh
  END SUBROUTINE BLDIF_D

