      hlsq = 15.0
    ELSE
      hlsq = hl**2
    END IF
    ehh = EXP(-(hlsq*hdcon))
    upw = 1.0 - 0.5*ehh
    upw_hl = ehh*hl*hdcon
    upw_hd = 0.5*ehh*hlsq
!
    upw_hk1 = upw_hl*hl_hk1 + upw_hd*hd_hk1
    upw_hk2 = upw_hl*hl_hk2 + upw_hd*hd_hk2
