!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
!*** End of declarations rewritten by SPAG
!
!
!---- calculate kinematic shape parameter (assuming air)
!     (from Whitfield )
    temp = (h-0.29*msq)/(0.113*msq+1.0)
    hkd = (hd-(temp*0.113+0.29)*msqd)/(0.113*msq+1.0)
    hk = temp
    temp = 1.0/(0.113*msq+1.0)
    hk_hd = -(temp*0.113*msqd/(0.113*msq+1.0))
    hk_h = temp
    temp = (-(0.113*hk)-.29)/(0.113*msq+1.0)
    hk_msqd = (-(0.113*hkd)-temp*0.113*msqd)/(0.113*msq+1.0)
    hk_msq = temp
  END SUBROUTINE HKIN_D

!*==HKIN.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
